/* 수학 개념 카드 데이터 (자동 생성: tools/build.py) */
window.CARDS=[{"n":"수와 연산","id":"num","br":[{"n":"수 세기","id":"num-count","t":[{"w":"수","en":"number","d":"물건이 몇 개인지, 몇 번째인지를 나타내는 [양~글자~모양]이에요.","ex":"사과 세 개 → 3, 두 번째 → 2","x":"숫자와 수는 완전히 같은 말이에요.","why":"숫자는 수를 쓰는 글자(0~9)이고, 수는 그 글자가 나타내는 양이에요.","ln":["숫자","자연수"]},{"w":"숫자","en":"numeral","d":"수를 쓰기 위한 [글자~단위~그림]예요. 0부터 9까지 10개로 모든 수를 써요.","ex":"25는 숫자 2와 5로 쓴 수예요.","x":"숫자는 0부터 10까지 11개예요.","why":"숫자는 0, 1, 2, …, 9 이렇게 10개뿐이에요. 10은 숫자 1과 0을 붙여 쓴 수예요.","ln":["수"]},{"w":"개수","en":"number of pieces","d":"물건이 [몇 개~얼마나 무거운지~어디에]인지 세어서 나온 수예요.","ex":"연필 4자루의 개수는 4","x":"크기가 큰 물건일수록 개수가 많아요.","why":"개수는 크기와 상관없이 하나, 둘 세어서 정해져요.","ln":["개(단위)"]},{"w":"개(단위)","en":"unit 'gae'","d":"물건을 하나씩 셀 때 수 뒤에 붙이는 [단위~숫자~기호]예요.","ex":"공 3개, 사탕 10개","x":"'개'는 무게를 나타내는 말이에요.","why":"'개'는 몇 번 셌는지를 나타내는 세는 단위예요.","ln":[]},{"w":"묶어서 세기","en":"counting in groups","d":"많은 것을 [똑같은 수~아무렇게나~한 개]씩 묶어서 세는 방법이에요.","ex":"10개씩 묶음 3개 → 30개","x":"묶어서 셀 때는 묶음마다 개수가 달라도 돼요.","why":"묶음마다 개수가 같아야 '몇씩 몇 묶음'으로 빨리 셀 수 있어요.","ln":["뛰어 세기"]},{"w":"뛰어 세기","en":"skip counting","d":"하나씩이 아니라 [몇씩~거꾸로~하나씩] 건너뛰며 세는 방법이에요.","ex":"5씩 뛰어 세기: 5, 10, 15, 20","x":"2씩 뛰어 세면 2, 3, 4, 5가 돼요.","why":"2씩 뛰어 세면 2, 4, 6, 8처럼 2만큼씩 커져요.","fig":"line","ln":["묶어서 세기"]},{"w":"순서","en":"order","d":"정한 기준에 따라 [차례대로 놓인~아무렇게나 섞인~한곳에 쌓인] 것이에요.","ex":"키가 큰 순서: 아빠, 엄마, 시훈","x":"순서는 기준이 없어도 정할 수 있어요.","why":"'큰 순서', '빠른 순서'처럼 기준이 있어야 순서를 정해요.","ln":["규칙"]},{"w":"짝","en":"pair","d":"둘이 서로 [한 쌍~한 줄~세 묶음]을 이루는 것이에요.","ex":"양말 한 짝 + 한 짝 = 한 켤레","x":"짝은 셋이 모인 것이에요.","why":"짝은 둘이 한 쌍을 이루는 거예요.","ln":["홀수","배수"]},{"w":"쌍","en":"pair","d":"두 개가 모여 [한 덩어리~두 덩어리~세 개]를 이루는 것이에요. 한 쌍 = 2개예요.","ex":"젓가락 한 쌍 = 2개, 두 쌍 = 4개","x":"젓가락 두 쌍은 젓가락 2개예요.","why":"한 쌍이 2개니까 두 쌍은 4개예요.","ln":["순서쌍","짝"]}]},{"n":"크기 비교","id":"num-compare","t":[{"w":"비교","en":"comparison","d":"둘 이상을 보고 [같은 점과 다른 점~이름만~색깔만]을 찾는 것이에요.","ex":"키 비교: 형이 동생보다 커요.","x":"비교할 때는 아무 기준 없이 '더 좋다'고 말해요.","why":"길이, 무게, 수처럼 무엇으로 비교하는지 기준이 있어야 해요.","ln":["분류하기"]},{"w":"같다","en":"equal","d":"두 수나 식의 값이 [서로 같은~서로 다른~더 큰] 것이에요. 기호 =로 나타내요.","ex":"2 + 5 = 7","x":"모양이 달라도 '같다'는 쓸 수 없어요.","why":"2 + 5와 7은 모양은 달라도 값이 같아서 같다고 해요.","ln":["합동","등호"]},{"w":"크기","en":"size","d":"길이, 넓이, 부피, 양 등이 [얼마나 큰지~무슨 색인지~어디 있는지]를 나타내는 정도예요.","ex":"두 사각형은 크기가 달라요.","x":"모양이 같으면 크기도 꼭 같아요.","why":"모양이 같아도 크기는 다를 수 있어요(작은 정사각형, 큰 정사각형).","ln":["길이","넓이","부피"]},{"w":"많다","en":"many","d":"어떤 기준보다 수나 양이 [넘는~모자란~같은] 것이에요. 반대말은 '적다'예요.","ex":"사탕 7개는 3개보다 많아요.","x":"'많다'는 길이를 비교할 때만 써요.","why":"'많다'는 수나 양을 비교할 때 써요. 길이는 '길다'예요.","ln":["적다"]},{"w":"적다","en":"few","d":"어떤 기준에 [미치지 못하는~넘치는~딱 맞는] 양이에요. 반대말은 '많다'예요.","ex":"구슬 2개는 5개보다 적어요.","x":"'적다'와 '작다'는 같은 뜻이에요.","why":"'적다'는 수·양이 모자란 것, '작다'는 크기가 작은 것이에요.","ln":["많다"]}]},{"n":"자릿값","id":"num-place","t":[{"w":"영","en":"zero","d":"아무것도 [없는~하나 있는~가득한] 것을 나타내는 수 0이에요.","ex":"5 − 5 = 0, 5 × 0 = 0","x":"0은 수가 아니에요.","why":"0도 '없음'을 나타내는 어엿한 수예요. 105처럼 빈 자리를 채우기도 해요.","fig":"line","ln":["자릿값","양수","음수"]},{"w":"십","en":"ten","d":"9보다 [1~10~2] 큰 수예요. 10이라고 써요.","ex":"손가락을 모두 펴면 10개","x":"10은 9보다 10 큰 수예요.","why":"10은 9보다 1 큰 수예요.","ln":["수"]},{"w":"백","en":"hundred","d":"99보다 1 큰 수, 10이 [10개~100개~2개]인 수예요. 100이라고 써요.","ex":"10원짜리 10개 = 100원","x":"100은 10이 100개인 수예요.","why":"100은 10이 10개인 수예요.","ln":["천","만"]},{"w":"천","en":"thousand","d":"100이 [10개~100개~1000개]인 수예요. 1000이라고 써요.","ex":"100원짜리 10개 = 1000원","x":"1000은 100이 100개인 수예요.","why":"1000은 100이 10개인 수예요.","ln":["백","만"]},{"w":"만","en":"ten thousand","d":"1000이 [10개~100개~1000개]인 수예요. 10000이라고 써요.","ex":"1000원짜리 10장 = 10000원","x":"10000은 0이 3개예요.","why":"10000은 1 뒤에 0이 4개 붙어요.","ln":["십","천"]},{"w":"억","en":"hundred million","d":"10000이 [10000개~10개~100개]인 수예요. 1 뒤에 0이 8개 붙어요.","ex":"100000000 = 1억","x":"1억은 1 뒤에 0이 4개 붙어요.","why":"1억은 1 뒤에 0이 8개예요. 0이 4개면 1만이에요.","ln":["만"]},{"w":"자릿값","en":"place value","d":"숫자가 [어느 자리~어떤 색~몇 번째 줄]에 있느냐에 따라 달라지는 값이에요.","ex":"333에서 맨 앞 3은 300, 가운데 3은 30, 끝 3은 3","x":"같은 숫자는 어느 자리에 있어도 값이 같아요.","why":"같은 3이라도 백의 자리면 300, 일의 자리면 3이에요.","fig":"place","ln":["십진법","이진법"]},{"w":"십진법","en":"decimal system","d":"자리가 하나 왼쪽으로 갈 때마다 값이 [10배~2배~100배]가 되는 수 쓰는 방법이에요.","ex":"일 → 십 → 백 → 천, 10이 되면 윗자리로 올려요.","x":"십진법에서는 9 다음에 바로 윗자리로 올리지 않아요.","why":"9 다음 10이 되면 일의 자리는 0, 십의 자리에 1을 올려요.","fig":"place","ln":["받아올림","이진법"]},{"w":"십진법의 전개식","en":"expanded form","d":"수를 [자리마다의 값의 합~자리 숫자의 곱~숫자의 개수]으로 풀어 쓴 식이에요.","ex":"534 = 5×100 + 3×10 + 4×1","x":"534 = 5 + 3 + 4라고 풀어 써요.","why":"각 숫자에 자릿값을 곱해야 해요: 5×100 + 3×10 + 4×1.","ln":["자릿값","십진법"]},{"w":"이진법","en":"binary system","d":"0과 [1~2~9] 두 숫자만 써서, 자리가 올라갈 때마다 2배가 되는 수 쓰는 방법이에요.","ex":"이진법 11(₂)은 2 + 1 = 3이에요.","x":"이진법에서는 0부터 9까지 다 써요.","why":"이진법은 0과 1만 써요. 2가 되면 바로 윗자리로 올려요.","ln":["십진법"]},{"w":"바이트","en":"byte","d":"컴퓨터가 다루는 정보의 양을 나타내는 [단위~숫자~기호]예요. 1바이트는 0과 1 여덟 칸이에요.","ex":"01000001 → 1바이트","x":"1바이트는 0과 1이 한 칸이에요.","why":"0 또는 1 한 칸은 1비트이고, 8비트가 모여야 1바이트예요.","ln":["이진법"]}]},{"n":"모으기와 가르기","id":"num-gather","t":[{"w":"모으기","en":"gather","d":"흩어진 것을 [한 군데로 합치는~여럿으로 나누는~줄 세우는] 것이에요. 덧셈의 바탕이에요.","ex":"2와 3을 모으면 5","x":"모으면 수가 작아져요.","why":"모으면 처음 각각보다 더 커져요(0을 모을 때만 그대로).","ln":["가르기"]},{"w":"가르기","en":"split","d":"한 수를 [두 수 이상으로 나누는~하나로 합치는~거꾸로 쓰는] 것이에요. 뺄셈의 바탕이에요.","ex":"7은 3과 4로 가를 수 있어요.","x":"7을 가르는 방법은 한 가지뿐이에요.","why":"7은 1과 6, 2와 5, 3과 4 …처럼 여러 가지로 가를 수 있어요.","ln":["모으기"]},{"w":"더하기","en":"add","d":"둘 이상의 수나 양을 [합쳐서 모으는~덜어 내는~똑같이 나누는] 것이에요.","ex":"3 더하기 4는 7","x":"더하기를 하면 늘 처음 수보다 작아져요.","why":"더하기는 합치는 것이라 0이 아닌 수를 더하면 커져요.","ln":["덧셈","모으기","빼기"]},{"w":"빼기","en":"subtract","d":"어떤 양에서 일부를 [덜어 내는~더 넣는~여러 번 더하는] 것이에요.","ex":"7 빼기 5는 2","x":"빼기는 순서를 바꿔도 답이 같아요.","why":"7 − 5 = 2이지만 5 − 7은 2가 아니에요. 빼기는 순서가 중요해요.","ln":["뺄셈","더하기"]},{"w":"합","en":"sum","d":"더한 [결과~차이~몫]예요.","ex":"3과 4의 합은 7","x":"3과 4의 합은 12예요.","why":"12는 3과 4를 곱한 값(곱)이에요. 합은 더한 값 7이에요.","ln":["더하기","모으기"]},{"w":"차","en":"difference","d":"두 수 중 큰 수에서 작은 수를 [뺀 값~더한 값~곱한 값]이에요.","ex":"4와 2의 차는 2","x":"2와 4의 차는 −2예요.","why":"차는 큰 수에서 작은 수를 빼서 구하니까 2예요.","ln":["빼기"]}]},{"n":"덧셈과 뺄셈","id":"num-addsub","t":[{"w":"덧셈","en":"addition","d":"두 수를 [더하는~빼는~나누는] 계산이에요. 결과를 '합'이라고 해요.","ex":"5 + 2 = 7","x":"덧셈은 순서를 바꾸면 답이 달라져요.","why":"3 + 5 = 5 + 3처럼 덧셈은 순서를 바꿔도 합이 같아요.","fig":"line","ln":["뺄셈"]},{"w":"뺄셈","en":"subtraction","d":"앞의 수에서 뒤의 수를 [빼는~더하는~곱하는] 계산이에요. 결과를 '차'라고 해요.","ex":"6 − 2 = 4","x":"6 − 2와 2 − 6은 답이 같아요.","why":"뺄셈은 순서를 바꾸면 답이 달라져요.","fig":"line","ln":["빼기","덧셈"]},{"w":"덧셈 기호","en":"addition sign","d":"덧셈을 나타내는 기호 [+~−~×]예요.","ex":"1 + 2 = 3","x":"덧셈 기호는 ×예요.","why":"덧셈 기호는 +이고, ×는 곱셈 기호예요.","ln":["뺄셈 기호"]},{"w":"뺄셈 기호","en":"subtraction sign","d":"뺄셈을 나타내는 기호 [−~+~÷]예요.","ex":"9 − 5 = 4","x":"뺄셈 기호는 ÷예요.","why":"뺄셈 기호는 −이고, ÷는 나눗셈 기호예요.","ln":["빼기","뺄셈","덧셈 기호"]},{"w":"받아올림","en":"carrying","d":"같은 자리 수끼리 더해서 [10~5~100] 이상이 되면 윗자리로 1을 올려 주는 것이에요.","ex":"27 + 8: 7 + 8 = 15 → 5 쓰고 1을 십의 자리로","x":"받아올림한 1은 그냥 버려요.","why":"올린 1은 윗자리에 꼭 더해야 해요: 27 + 8 = 35.","fig":"vcalc","ln":["받아내림"]},{"w":"받아내림","en":"borrowing","d":"뺄 수 없을 때 [윗자리에서 10을~아랫자리에서 1을~옆 수에서 2를] 빌려 와 계산하는 것이에요.","ex":"45 − 27: 5에서 7을 못 빼니 십의 자리에서 10을 빌려 15 − 7 = 8","x":"받아내림할 때 윗자리는 그대로 둬요.","why":"빌려 준 윗자리는 1 줄여야 해요: 45 − 27에서 4는 3이 돼요.","ln":["받아올림"]},{"w":"가로셈","en":"horizontal calculation","d":"식을 [옆으로 한 줄로~위아래로~동그랗게] 써서 계산하는 방법이에요.","ex":"3 + 4 = 7","x":"가로셈과 세로셈은 답이 달라요.","why":"쓰는 모양만 다르고 답은 같아요.","ln":["세로셈"]},{"w":"세로셈","en":"vertical calculation","d":"수를 [자리를 맞춰 위아래로~옆으로 한 줄로~아무렇게나] 써서 계산하는 방법이에요.","ex":"  27 아래에 +8, 일의 자리끼리 맞춰 써요.","x":"세로셈은 자리를 맞추지 않아도 돼요.","why":"일의 자리는 일의 자리끼리 줄을 맞춰야 틀리지 않아요.","fig":"vcalc","ln":["가로셈"]},{"w":"합계","en":"sum total","d":"여러 값을 [모두 더한~모두 곱한~가장 큰] 결과예요.","ex":"500원 + 200원 + 100원 = 합계 800원","x":"합계는 가장 비싼 물건의 값이에요.","why":"합계는 모든 값을 다 더한 거예요.","ln":["덧셈"]},{"w":"거스름돈","en":"change","d":"물건값보다 돈을 더 냈을 때 [돌려받는~더 내는~빌리는] 돈이에요.","ex":"1000원 내고 600원짜리를 사면 거스름돈 400원","x":"거스름돈은 낸 돈과 물건값을 더해서 구해요.","why":"거스름돈 = 낸 돈 − 물건값이에요.","ln":["빼기"]}]},{"n":"곱셈","id":"num-mul","t":[{"w":"곱셈","en":"multiplication","d":"같은 수를 [여러 번 더하는~여러 번 빼는~나누는] 것을 간단히 하는 계산이에요.","ex":"3 × 4 = 3 + 3 + 3 + 3 = 12","x":"3 × 4는 3 + 4와 같아요.","why":"3 × 4는 3을 4번 더한 것이라 12예요. 3 + 4는 7이에요.","fig":"array","ln":["곱","곱셈 기호"]},{"w":"곱","en":"product","d":"곱셈을 해서 나온 [결과~나머지~차이]예요.","ex":"3과 4의 곱은 12","x":"곱은 늘 두 수 중 큰 수보다 커요.","why":"1 × 5 = 5, 0 × 5 = 0처럼 크지 않을 때도 있어요.","ln":["곱셈","배수"]},{"w":"곱셈 기호","en":"multiplication sign","d":"곱셈을 나타내는 기호 [×~+~÷]예요.","ex":"54 × 5 = 270","x":"곱셈 기호는 ÷예요.","why":"곱셈 기호는 ×이고, ÷는 나눗셈 기호예요.","ln":["곱","곱셈"]},{"w":"곱셈 구구","en":"multiplication table","d":"1부터 9까지의 수끼리 [곱한 값~더한 값~뺀 값]을 모아 놓은 것이에요.","ex":"7 × 8 = 56","x":"곱셈 구구는 덧셈을 정리한 표예요.","why":"곱셈 구구는 곱셈을 정리한 표예요.","fig":"grid99","ln":["구구단"]},{"w":"구구단","en":"times tables","d":"곱셈 구구를 [단마다~색깔마다~짝수만] 묶어 부르는 말이에요.","ex":"7단: 7, 14, 21, 28 …","x":"7단은 7씩 뛰어 세기와 아무 관계가 없어요.","why":"7단의 답은 7, 14, 21 …로 7씩 뛰어 센 수와 같아요.","ln":["곱셈 구구"]},{"w":"거듭제곱","en":"power","d":"같은 수를 [여러 번 곱한~여러 번 더한~한 번 나눈] 것이에요.","ex":"2 × 2 × 2 = 2³ (2의 세제곱) = 8","x":"2³은 2 × 3이라서 6이에요.","why":"2³은 2를 세 번 곱한 것이라 2 × 2 × 2 = 8이에요.","ln":["제곱"]},{"w":"제곱","en":"square","d":"같은 수를 [두 번~세 번~열 번] 곱한 것이에요.","ex":"3의 제곱: 3 × 3 = 3² = 9","x":"3의 제곱은 3 × 2 = 6이에요.","why":"3의 제곱은 3 × 3 = 9예요.","fig":"square","ln":["거듭제곱"]}]},{"n":"나눗셈","id":"num-div","t":[{"w":"나누다","en":"divide","d":"하나를 [둘 이상으로 가르는~하나로 합치는~두 배로 늘리는] 것이에요.","ex":"귤 6개를 3명이 똑같이 나누면 한 명에 2개","x":"나누면 전체 양이 줄어들어요.","why":"나누어도 모두 합치면 전체 양은 그대로예요.","ln":["가르기","나눗셈"]},{"w":"등분","en":"equal parts","d":"[똑같은 크기로~아무 크기로~두 개로만] 나누는 것이에요.","ex":"피자를 6등분 → 똑같은 조각 6개","x":"크기가 다른 6조각도 6등분이에요.","why":"6등분은 6조각의 크기가 모두 같아야 해요.","fig":"frac6","ln":["분수","나누다"]},{"w":"나눗셈","en":"division","d":"어떤 수를 [똑같이 나누는~여러 번 더하는~합치는] 계산이에요.","ex":"6 ÷ 2 = 3 (6은 나누어지는 수, 2는 나누는 수, 3은 몫)","x":"6 ÷ 2와 2 ÷ 6은 답이 같아요.","why":"나눗셈도 순서를 바꾸면 답이 달라져요.","ln":["나누어떨어지다","나머지"]},{"w":"나눗셈 기호","en":"division sign","d":"나눗셈을 나타내는 기호 [÷~×~−]예요.","ex":"8 ÷ 2 = 4","x":"나눗셈 기호는 ×예요.","why":"나눗셈 기호는 ÷이고, ×는 곱셈 기호예요.","ln":["나누다"]},{"w":"몫","en":"quotient","d":"나눗셈을 해서 나온 [답~나머지~나누는 수]이에요. 한 묶음의 양이나 묶음의 수를 알려 줘요.","ex":"6 ÷ 3 = 2에서 몫은 2","x":"몫은 나머지보다 항상 커요.","why":"그렇지 않아요. 5 ÷ 3 = 1 … 2처럼 몫 1이 나머지 2보다 작을 수도 있어요.","ln":["나눗셈","나머지"]},{"w":"나머지","en":"remainder","d":"똑같이 나누고 [남은 수~나눈 수~더한 수]예요. 나머지는 나누는 수보다 항상 작아요.","ex":"5 ÷ 2 = 2 … 1에서 나머지는 1","x":"나머지는 몫보다 항상 작아요.","why":"나머지는 '나누는 수'보다 작아요. 몫과는 상관없어요: 7 ÷ 4 = 1 … 3.","ln":["나눗셈","몫"]},{"w":"나누어떨어지다","en":"divide evenly","d":"나눗셈에서 나머지가 [0~1~몫]이 되는 것이에요.","ex":"15 ÷ 5 = 3 → 나머지 0, 나누어떨어져요.","x":"16 ÷ 5는 나누어떨어져요.","why":"16 ÷ 5 = 3 … 1로 나머지가 있어서 나누어떨어지지 않아요.","ln":["나눗셈","나누다","나머지"]}]},{"n":"계산 규칙","id":"num-rule","t":[{"w":"계산","en":"calculation","d":"주어진 수나 식의 값을 [규칙에 따라 구하는~눈으로 어림하는~그림으로 그리는] 것이에요.","ex":"3 + 2를 계산하면 5","x":"계산은 답만 맞으면 순서는 아무래도 돼요.","why":"식에 따라 계산하는 순서가 정해져 있어요(괄호 먼저, × ÷ 먼저).","ln":["사칙연산"]},{"w":"사칙연산","en":"four operations","d":"[덧셈·뺄셈·곱셈·나눗셈~덧셈과 뺄셈~곱셈과 제곱] 네 가지 계산을 함께 부르는 말이에요.","ex":"+, −, ×, ÷","x":"사칙연산은 덧셈과 뺄셈 두 가지예요.","why":"사칙(四則)은 네 가지라는 뜻이에요: +, −, ×, ÷.","ln":["혼합 계산"]},{"w":"혼합 계산","en":"mixed calculation","d":"덧셈·뺄셈·곱셈·나눗셈이 [섞여 있는~하나만 있는~없는] 식을 계산하는 것이에요.","ex":"2 + 5 × 3 = 2 + 15 = 17","x":"2 + 5 × 3은 앞에서부터 계산해서 21이에요.","why":"곱셈을 먼저 해야 해요: 5 × 3 = 15, 2 + 15 = 17.","ln":["사칙연산"]},{"w":"괄호","en":"parentheses","d":"식에서 [먼저 계산할~나중에 계산할~안 써도 되는] 부분을 묶는 기호예요.","ex":"5 × (3 + 5) = 5 × 8 = 40","x":"괄호가 있어도 곱셈을 먼저 해요.","why":"괄호 안을 가장 먼저 계산해요.","ln":["혼합 계산"]},{"w":"교환법칙","en":"commutative law","d":"두 수의 [순서를 바꾸어~크기를 바꾸어~기호를 바꾸어] 계산해도 결과가 같은 성질이에요.","ex":"3 + 4 = 4 + 3, 4 × 3 = 3 × 4","x":"뺄셈에도 교환법칙이 있어요.","why":"5 − 3 = 2지만 3 − 5는 2가 아니라서 뺄셈에는 없어요.","ln":["덧셈에 대한 교환법칙","곱셈에 대한 교환법칙"]},{"w":"덧셈에 대한 교환법칙","en":"commutative law of addition","d":"덧셈은 두 수의 [순서를 바꿔도~하나를 빼도~두 배로 해도] 합이 같아요.","ex":"3 + 5 = 5 + 3 = 8","x":"덧셈에서 순서를 바꾸면 합이 달라져요.","why":"3 + 5도 8, 5 + 3도 8로 같아요.","ln":["곱셈에 대한 교환법칙"]},{"w":"곱셈에 대한 교환법칙","en":"commutative law of multiplication","d":"곱셈은 두 수의 [순서를 바꿔도~하나를 빼도~1을 더해도] 곱이 같아요.","ex":"8 × 9 = 9 × 8 = 72","x":"8 × 9와 9 × 8은 곱이 달라요.","why":"둘 다 72로 같아요. 그래서 구구단 절반만 외워도 돼요.","fig":"array","ln":["교환법칙"]},{"w":"결합법칙","en":"associative law","d":"세 수를 더하거나 곱할 때 [어느 두 수를 먼저 묶어도~순서대로만~큰 수부터만] 결과가 같은 성질이에요.","ex":"(2 + 3) + 4 = 2 + (3 + 4)","x":"결합법칙은 뺄셈에도 늘 성립해요.","why":"(9 − 4) − 2 = 3, 9 − (4 − 2) = 7로 달라서 뺄셈에는 없어요.","ln":["덧셈에 대한 결합법칙","곱셈에 대한 결합법칙"]},{"w":"덧셈에 대한 결합법칙","en":"associative law of addition","d":"세 수를 더할 때 [앞의 두 수든 뒤의 두 수든~꼭 앞의 두 수만~가장 큰 수만] 먼저 더해도 합이 같아요.","ex":"(3 + 5) + 2 = 3 + (5 + 2) = 10","x":"괄호 위치가 바뀌면 합도 달라져요.","why":"덧셈만 있을 때는 괄호 위치가 바뀌어도 합이 같아요.","ln":["곱셈에 대한 결합법칙"]},{"w":"곱셈에 대한 결합법칙","en":"associative law of multiplication","d":"세 수를 곱할 때 [어느 두 수를 먼저 곱해도~앞에서부터만~큰 수부터만] 곱이 같아요.","ex":"(2 × 3) × 6 = 2 × (3 × 6) = 36","x":"(2 × 3) × 6과 2 × (3 × 6)은 곱이 달라요.","why":"6 × 6 = 36, 2 × 18 = 36으로 같아요.","ln":["결합법칙"]},{"w":"분배법칙","en":"distributive law","d":"두 수의 합에 어떤 수를 곱한 것은 [각각 곱해서 더한~더한 뒤 빼는~하나만 곱한] 것과 같은 성질이에요.","ex":"3 × (4 + 5) = 3 × 4 + 3 × 5 = 27","x":"3 × (4 + 5) = 3 × 4 + 5예요.","why":"5에도 3을 곱해야 해요: 12 + 15 = 27.","ln":["결합법칙","교환법칙"]}]},{"n":"계산 확인과 도구","id":"num-check","t":[{"w":"기호","en":"sign","d":"뜻을 [짧게 나타내려고 정한 표시~긴 문장~그림 이야기]예요.","ex":"+ − × ÷ = < >","x":"기호는 나라마다 뜻이 제멋대로예요.","why":"수학 기호는 모두가 같은 뜻으로 쓰기로 약속한 거예요.","ln":["사칙연산"]},{"w":"검산","en":"check","d":"계산한 답이 맞는지 [다른 방법으로 다시~똑같이 한 번 더~눈으로만] 확인하는 것이에요.","ex":"11 − 7 = 4 → 4 + 7 = 11 이니까 맞아요.","x":"검산은 같은 식을 그대로 다시 풀어 보는 거예요.","why":"덧셈은 뺄셈으로, 나눗셈은 곱셈으로처럼 다른 길로 확인해야 실수를 찾기 쉬워요.","ln":["거꾸로 풀기"]},{"w":"계산기","en":"calculator","d":"계산을 [쉽고 빠르게 도와주는~대신 생각해 주는~문제를 내 주는] 기계예요.","ex":"전자계산기","x":"계산기가 있으면 식을 세울 필요가 없어요.","why":"무엇을 계산할지(식)는 내가 정해야 해요.","ln":["계산","주판"]},{"w":"주판","en":"abacus","d":"알을 위아래로 움직여 [계산하는~길이를 재는~무게를 다는] 옛 도구예요.","ex":"윗알 1개 = 5, 아랫알 1개 = 1","x":"주판알은 모두 1을 나타내요.","why":"윗알 하나는 5, 아랫알 하나는 1을 나타내요.","ln":["계산기"]}]},{"n":"짝수, 홀수, 약수와 배수","id":"num-factor","t":[{"w":"짝수","en":"even number","d":"[2로 나누어떨어지는~3으로 나누어떨어지는~1로만 나누어떨어지는] 자연수예요.","ex":"2, 4, 6, 8 …","x":"짝수는 끝자리가 늘 0이에요.","why":"끝자리가 0, 2, 4, 6, 8이면 짝수예요.","ln":["홀수","배수"]},{"w":"홀수","en":"odd number","d":"2로 나누면 나머지가 [1~0~2]인 자연수예요.","ex":"1, 3, 5, 7 …","x":"9는 짝수예요.","why":"9 ÷ 2 = 4 … 1이라 홀수예요.","ln":["짝수"]},{"w":"약수","en":"divisor","d":"어떤 수를 [나누어떨어지게 하는~곱해서 만드는~더해서 만드는] 수예요.","ex":"8의 약수: 1, 2, 4, 8","x":"8은 8의 약수가 아니에요.","why":"어떤 수는 자기 자신으로 나누어떨어지니까 자기 자신도 약수예요.","ln":["배수","최대공약수"]},{"w":"배수","en":"multiple","d":"어떤 수를 [1배, 2배, 3배 …~1, 2, 3을 더한~반으로 나눈] 한 수예요.","ex":"3의 배수: 3, 6, 9, 12 …","x":"3의 배수는 3, 6, 9 셋뿐이에요.","why":"배수는 끝없이 많아요.","ln":["공배수","최소공배수"]},{"w":"공약수","en":"common divisor","d":"두 수 이상의 [약수에 공통으로 들어 있는~배수에 공통으로 들어 있는~가장 큰] 수예요.","ex":"12와 18의 공약수: 1, 2, 3, 6","x":"1은 공약수가 될 수 없어요.","why":"1은 모든 수의 약수라서 언제나 공약수예요.","ln":["약수","인수","최대공약수"]},{"w":"공배수","en":"common multiple","d":"두 수 이상의 [배수에 공통으로 들어 있는~약수에 공통으로 들어 있는~합인] 수예요.","ex":"2와 3의 공배수: 6, 12, 18 …","x":"2와 3의 공배수는 5예요.","why":"5는 2와 3을 더한 수예요. 공배수는 6, 12, 18 …예요.","ln":["배수","최소공배수"]},{"w":"최대공약수","en":"greatest common divisor","d":"공약수 중에서 [가장 큰~가장 작은~가운데] 수예요.","ex":"8과 12의 공약수 1, 2, 4 → 최대공약수 4","x":"8과 12의 최대공약수는 12예요.","why":"12는 8의 약수가 아니에요. 최대공약수는 4예요.","ln":["약수","공약수"]},{"w":"최소공배수","en":"least common multiple","d":"공배수 중에서 [가장 작은~가장 큰~두 번째] 수예요.","ex":"3과 4의 공배수 12, 24 … → 최소공배수 12","x":"최소공배수는 두 수를 곱한 것과 항상 같아요.","why":"4와 6은 곱이 24지만 최소공배수는 12예요.","ln":["배수","공배수"]},{"w":"소수(素數)","en":"prime number","d":"1과 [자기 자신~2~10]만을 약수로 가지는 1보다 큰 수예요.","ex":"2, 3, 5, 7, 11, 13 …","x":"1은 소수예요.","why":"1은 약수가 1 하나뿐이라 소수가 아니에요. 2는 짝수지만 소수예요.","ln":["소인수분해"]},{"w":"인수","en":"factor","d":"어떤 수를 [몇 개의 수의 곱으로~몇 개의 수의 합으로~빼기로] 나타낼 때 곱해지는 각각의 수예요.","ex":"6 = 2 × 3에서 2와 3은 6의 인수","x":"6 = 1 + 5에서 1과 5는 6의 인수예요.","why":"인수는 덧셈이 아니라 곱셈으로 나타낼 때의 수예요.","ln":["소인수분해"]},{"w":"소인수분해","en":"prime factorization","d":"어떤 수를 [소수들만의 곱~아무 수의 곱~소수들의 합]으로 나타내는 것이에요.","ex":"30 = 2 × 3 × 5","x":"30 = 5 × 6도 소인수분해예요.","why":"6은 소수가 아니에요. 6을 더 쪼개 2 × 3 × 5로 써야 해요.","ln":["소수(素數)","인수"]}]},{"n":"분수","id":"num-frac","t":[{"w":"전체","en":"whole","d":"어떤 것을 이루는 [모든 것~한 조각~남은 것]이에요. 분수에서는 보통 1로 봐요.","ex":"피자 한 판 전체 = 1","x":"전체를 나누면 전체가 늘어나요.","why":"조각 수만 늘고, 모두 합치면 전체 1 그대로예요.","fig":"frac8","ln":["분수","부분"]},{"w":"부분","en":"part","d":"전체를 여러 개로 나눈 것 중 [일부~전부~두 배]예요.","ex":"피자 8조각 중 1조각 → 전체의 1/8","x":"부분은 전체보다 클 수도 있어요.","why":"부분은 전체 중의 일부라 전체보다 크지 않아요.","fig":"frac8","ln":["전체"]},{"w":"반","en":"half","d":"전체를 똑같이 [둘로~셋으로~넷으로] 나눈 것 중 하나예요. 1/2이에요.","ex":"사과 반쪽 = 사과의 1/2","x":"크기가 다르게 둘로 나눠도 반이에요.","why":"똑같이 나눠야 반이에요.","fig":"frac2","ln":["전체"]},{"w":"분수","en":"fraction","d":"전체를 똑같이 나눈 것 중 [몇 개인지~몇 번째인지~얼마나 무거운지]를 나타내는 수예요.","ex":"3/4: 똑같이 4로 나눈 것 중 3","x":"1/4은 4를 1로 나눈 것이에요.","why":"1/4은 1을 똑같이 4로 나눈 것 중 1이에요.","fig":"frac4","ln":["분모","분자"]},{"w":"분모","en":"denominator","d":"분수에서 가로선 [아래~위~옆]에 있는 수예요. 전체를 몇으로 나눴는지 알려 줘요.","ex":"3/4에서 분모는 4","x":"분모가 클수록 한 조각이 커요.","why":"분모가 클수록 더 잘게 나눠서 한 조각은 작아져요: 1/8 < 1/2.","fig":"frac4","ln":["분수","분자"]},{"w":"분자","en":"numerator","d":"분수에서 가로선 [위~아래~옆]에 있는 수예요. 나눈 것 중 몇 개인지 알려 줘요.","ex":"3/4에서 분자는 3","x":"분자는 전체를 몇으로 나눴는지 알려 줘요.","why":"그건 분모예요. 분자는 그중 몇 개인지예요.","fig":"frac4","ln":["분수","분모"]},{"w":"단위분수","en":"unit fraction","d":"분자가 [1인~0인~분모와 같은] 분수예요.","ex":"1/2, 1/3, 1/5","x":"2/5는 단위분수예요.","why":"분자가 2라서 단위분수가 아니에요. 2/5는 1/5이 2개예요.","ln":["분수"]},{"w":"진분수","en":"proper fraction","d":"분자가 분모보다 [작은~큰~같은] 분수예요. 1보다 작아요.","ex":"1/5, 3/4","x":"4/4는 진분수예요.","why":"분자와 분모가 같으면 1이라 가분수예요.","ln":["가분수","분수"]},{"w":"가분수","en":"improper fraction","d":"분자가 분모와 [같거나 큰~늘 작은~0인] 분수예요.","ex":"4/4, 7/3","x":"7/3은 1보다 작아요.","why":"분자가 분모보다 크니까 1보다 커요(2와 1/3).","ln":["진분수","분수"]},{"w":"대분수","en":"mixed number","d":"[자연수와 진분수~두 진분수~자연수와 가분수]로 이루어진 분수예요.","ex":"3 1/5 = 3 + 1/5","x":"3 1/5은 3 × 1/5이에요.","why":"대분수는 자연수와 진분수를 더한 거예요: 3 + 1/5.","ln":["분수","진분수"]}]},{"n":"분수 계산","id":"num-fraccalc","t":[{"w":"약분","en":"reduction","d":"분모와 분자를 [같은 수로 나누어~같은 수를 빼서~다른 수로 나누어] 더 간단한 분수로 만드는 것이에요.","ex":"4/10 → 둘 다 2로 나누면 2/5","x":"약분하면 분수의 크기가 작아져요.","why":"약분해도 크기는 그대로예요: 4/10 = 2/5.","ln":["최대공약수","분수","기약분수"]},{"w":"기약분수","en":"irreducible fraction","d":"분모와 분자의 공약수가 [1뿐이라~2뿐이라~없어서] 더는 약분이 안 되는 분수예요.","ex":"4/5, 2/3","x":"6/9는 기약분수예요.","why":"6과 9는 3으로 나눌 수 있어 2/3이 되니 기약분수가 아니에요.","ln":["약분","최대공약수"]},{"w":"통분","en":"common denominator","d":"분수의 크기는 그대로 두고 [분모를 같게~분자를 같게~모두 1로] 만드는 것이에요.","ex":"1/2과 1/3 → 3/6과 2/6","x":"통분하면 분수의 크기가 바뀌어요.","why":"분모와 분자에 같은 수를 곱해서 크기는 그대로예요.","ln":["공통분모"]},{"w":"공통분모","en":"common denominator","d":"통분해서 [같아진 분모~같아진 분자~더한 분모]예요.","ex":"1/4과 1/6을 통분한 3/12, 2/12에서 공통분모는 12","x":"분모가 다른 분수도 그대로 분자끼리 더하면 돼요.","why":"분모를 같게(공통분모) 만든 뒤에야 분자끼리 더할 수 있어요.","ln":["통분","분모"]},{"w":"역수","en":"reciprocal","d":"곱해서 [1이~0이~10이] 되게 하는 수예요. 분수는 분모와 분자를 뒤집으면 돼요.","ex":"2/5의 역수는 5/2 (2/5 × 5/2 = 1)","x":"3의 역수는 −3이에요.","why":"3 × 1/3 = 1이니까 3의 역수는 1/3이에요.","ln":["분모","분자"]}]},{"n":"소수","id":"num-dec","t":[{"w":"소수(小數)","en":"decimal","d":"1보다 작은 부분을 [소수점을 써서~분수 모양으로~그림으로] 나타낸 수예요.","ex":"0.1 = 1/10, 31.54","x":"0.5는 0.45보다 작아요.","why":"0.5 = 0.50이라 0.45보다 커요. 자릿수가 많다고 크지 않아요.","fig":"line","ln":["소수점"]},{"w":"소수점","en":"decimal point","d":"소수에서 [자연수 부분과 소수 부분을 나누는~자리를 꾸미는~끝을 알리는] 점이에요.","ex":"42.6에서 . (사십이 점 육)","x":"소수점이 없어도 0.5와 5는 같아요.","why":"소수점 위치가 바뀌면 값이 10배씩 달라져요.","ln":["소수(小數)"]},{"w":"유한소수","en":"finite decimal","d":"소수점 아래 숫자가 [끝이 있는~끝없이 이어지는~하나도 없는] 소수예요.","ex":"0.1, 0.0009","x":"0.333 …은 유한소수예요.","why":"3이 끝없이 이어지니까 무한소수예요.","ln":["무한소수"]},{"w":"무한소수","en":"infinite decimal","d":"소수점 아래 숫자가 [끝없이 이어지는~끝이 있는~0뿐인] 소수예요.","ex":"1/3 = 0.333 …, 원주율 3.14159 …","x":"무한소수는 자릿수가 많으니까 아주 큰 수예요.","why":"0.333 …은 1보다도 작아요. 크기와 자릿수는 상관없어요.","ln":["유한소수","원주율","순환소수"]},{"w":"순환소수","en":"repeating decimal","d":"무한소수 중 [같은 숫자 묶음이 되풀이되는~숫자가 마구 섞인~끝이 있는] 소수예요.","ex":"0.333 …, 0.285714285714 …","x":"원주율 3.14159 …은 순환소수예요.","why":"원주율은 되풀이되는 묶음이 없어서 순환소수가 아니에요.","ln":["순환마디","무한소수"]},{"w":"순환마디","en":"repetend","d":"순환소수에서 [되풀이되는 숫자 묶음~맨 앞 숫자~소수점]이에요.","ex":"0.285714285714 …의 순환마디는 285714","x":"0.121212 …의 순환마디는 1이에요.","why":"되풀이되는 묶음은 12예요.","ln":["순환소수","무한소수"]}]},{"n":"어림하기","id":"num-round","t":[{"w":"어림하기","en":"estimation","d":"정확하게 재거나 계산하지 않고 [대강 짐작하는~정확히 구하는~포기하는] 것이에요.","ex":"498 + 203 → 약 500 + 200 = 700","x":"어림한 값은 틀린 답이에요.","why":"어림은 빠르게 크기를 짐작하는 방법이고, 정확한 답이 맞는지 확인할 때도 써요.","ln":["측정","계산"]},{"w":"반올림","en":"rounding","d":"구하려는 자리 바로 아래 숫자가 [5 이상이면 올리고 4 이하면 버리는~늘 버리는~늘 올리는] 방법이에요.","ex":"5.3 → 5, 5.7 → 6","x":"2.5를 일의 자리까지 반올림하면 2예요.","why":"바로 아래 숫자가 5이면 올리니까 3이에요.","fig":"line","ln":["올림","버림"]},{"w":"올림","en":"rounding up","d":"구하려는 자리 아래에 0이 아닌 숫자가 있으면 [무조건 올리는~무조건 버리는~5부터 올리는] 방법이에요.","ex":"버스 1대에 40명, 41명이면 2대가 필요 → 올림","x":"341을 백의 자리까지 올림하면 300이에요.","why":"아래에 41이 있으니 올려서 400이에요.","ln":["반올림","버림"]},{"w":"버림","en":"rounding down","d":"구하려는 자리 아래 수를 [모두 버리는~모두 올리는~반만 버리는] 방법이에요.","ex":"3800원을 천 원짜리 지폐로만 바꾸면 3장(3000원), 800원은 남아요.","x":"169를 십의 자리까지 버림하면 170이에요.","why":"버림은 아래를 버리니까 160이에요.","ln":["올림","반올림"]},{"w":"이상","en":"not less than","d":"기준 수와 [같거나 큰~같거나 작은~딱 같은] 수예요.","ex":"5 이상: 5, 6, 7 …","x":"5 이상에는 5가 들어가지 않아요.","why":"'이상'은 기준 5도 들어가요.","fig":"range","ln":["이하","초과","미만"]},{"w":"이하","en":"not greater than","d":"기준 수와 [같거나 작은~같거나 큰~더 큰] 수예요.","ex":"10 이하: 10, 9, 8 …","x":"10 이하에는 10이 들어가지 않아요.","why":"'이하'는 기준 10도 들어가요.","fig":"range","ln":["이상","초과","미만"]},{"w":"초과","en":"more than","d":"기준 수보다 [큰~작은~같은] 수예요. 기준 수는 들어가지 않아요.","ex":"10 초과: 11, 12 … (10은 아님)","x":"10 초과에는 10이 들어가요.","why":"'초과'는 기준보다 큰 것만이라 10은 빠져요.","fig":"range","ln":["미만"]},{"w":"미만","en":"less than","d":"기준 수보다 [작은~큰~같은] 수예요. 기준 수는 들어가지 않아요.","ex":"6 미만인 자연수: 1, 2, 3, 4, 5","x":"6 미만에는 6이 들어가요.","why":"'미만'은 기준보다 작은 것만이라 6은 빠져요.","fig":"range","ln":["이하"]},{"w":"오차","en":"error","d":"정확한 값(참값)과 [어림한 값의 차이~어림한 값의 합~참값 그 자체]예요.","ex":"참값 4.67, 어림값 4.7 → 오차 0.03","x":"오차는 어림한 값과 같아요.","why":"오차는 두 값의 차이예요: 4.7 − 4.67 = 0.03.","ln":[]}]},{"n":"수의 범위 넓히기","id":"num-ext","t":[{"w":"자연수","en":"natural number","d":"[1, 2, 3 …처럼~0, 1, 2 …처럼~−1, −2 …처럼] 물건을 셀 때 쓰는 수예요.","ex":"1, 2, 3, 100","x":"0은 자연수예요.","why":"자연수는 1부터 시작해요. 0은 자연수가 아니에요.","ln":["정수","수"]},{"w":"연속하는 수","en":"consecutive numbers","d":"[1씩 커지는~2씩 커지는~마구 섞인] 수들이에요.","ex":"3, 4, 5, 6","x":"2, 4, 6, 8은 연속하는 수예요.","why":"2씩 커지니까 연속하는 수가 아니에요(연속하는 짝수예요).","ln":["수열","규칙"]},{"w":"수직선","en":"number line","d":"직선 위에 [같은 간격으로~아무 간격으로~하나만] 눈금을 긋고 수를 대응시킨 선이에요.","ex":"0 기준 오른쪽이 양수, 왼쪽이 음수","x":"수직선에서 눈금 간격은 달라도 돼요.","why":"같은 크기만큼 같은 간격이어야 수의 크기를 바르게 볼 수 있어요.","fig":"line","ln":["눈금","대응"]},{"w":"양수","en":"positive number","d":"0보다 [큰~작은~같은] 수예요.","ex":"+1, 2, 3.5","x":"0은 양수예요.","why":"0은 양수도 음수도 아니에요.","fig":"line","ln":["음수"]},{"w":"음수","en":"negative number","d":"0보다 [작은~큰~같은] 수예요. 앞에 −를 붙여요.","ex":"영하 5도 = −5°C","x":"−5는 −1보다 커요.","why":"수직선에서 −5가 더 왼쪽이니 −5 < −1이에요.","fig":"line","ln":["양수"]},{"w":"정수","en":"integer","d":"[양의 정수, 0, 음의 정수~자연수와 분수~소수만]를 모두 합한 수예요.","ex":"… −2, −1, 0, 1, 2 …","x":"1/2도 정수예요.","why":"1/2은 분수예요. 정수는 눈금마다 딱 떨어지는 수예요.","fig":"line","ln":["자연수","음수","영"]},{"w":"유리수","en":"rational number","d":"[분수로 나타낼 수 있는~분수로 못 나타내는~0뿐인] 수예요.","ex":"1/2, 3 (= 3/1), 0.25 (= 1/4)","x":"자연수는 유리수가 아니에요.","why":"3 = 3/1처럼 자연수도 분수로 쓸 수 있으니 유리수예요.","ln":["분수"]},{"w":"절댓값","en":"absolute value","d":"수직선에서 [0부터 떨어진 거리~1부터 떨어진 거리~부호]예요.","ex":"−4의 절댓값 4, +4의 절댓값 4","x":"−4의 절댓값은 −4예요.","why":"거리는 음수가 될 수 없어서 4예요.","fig":"line","ln":["거리"]}]}]},{"n":"도형","id":"shape","br":[{"n":"점과 선","id":"shape-line","t":[{"w":"점","en":"point","d":"위치만 있고 [크기가 없는~크기가 큰~색이 있는] 가장 단순한 도형이에요.","ex":"꼭짓점, 교점, 원점","x":"점은 크게 찍을수록 더 큰 점이에요.","why":"수학의 점은 위치만 나타내고 크기가 없어요.","fig":"pt","ln":["꼭짓점","교점"]},{"w":"선","en":"line","d":"점이 [움직이며 지나간~가만히 멈춰 있던~처음 찍힌] 자리예요. 길이는 있지만 넓이는 없어요.","ex":"곧은 선, 굽은 선","x":"선에는 넓이가 있어요.","why":"선은 길이만 있고 넓이·두께는 없어요.","fig":"lines","ln":["곡선","직선","선분"]},{"w":"곧은 선","en":"straight line","d":"[구부러지지 않고 곧게~구불구불하게~둥글게] 뻗은 선이에요.","ex":"자를 대고 그은 선","x":"곧은 선은 꼭 가로로만 그어야 해요.","why":"비스듬해도 구부러지지 않으면 곧은 선이에요.","fig":"lines","ln":["직선"]},{"w":"굽은 선","en":"curved line","d":"[구부러져 휘어진~곧게 뻗은~끊어진] 선이에요.","ex":"무지개 모양 선","x":"굽은 선은 동그랗게 닫혀 있어야 해요.","why":"열려 있어도 휘어 있으면 굽은 선이에요.","fig":"lines","ln":["곧은 선","곡선"]},{"w":"곡선","en":"curve","d":"[부드럽게 휘어진~꺾인~곧은] 선이에요. 굽은 선과 같은 말이에요.","ex":"비행기가 남긴 구불구불한 구름","x":"곡선은 자로 그어요.","why":"자로는 곧은 선을 그어요. 곡선은 휘어 있어요.","fig":"lines","ln":["직선"]},{"w":"직선","en":"straight line","d":"양쪽으로 [끝없이 곧게 뻗은~한쪽만 뻗은~양 끝이 있는] 선이에요.","ex":"직선 AB는 점 A와 B를 지나 양쪽으로 끝없이 뻗어요.","x":"직선은 양 끝이 있어서 길이를 잴 수 있어요.","why":"양쪽 끝이 없어서 길이를 잴 수 없어요. 양 끝이 있는 건 선분이에요.","fig":"lineseg","ln":["곡선","선분"]},{"w":"선분","en":"line segment","d":"두 점을 [곧게 이은~구불구불 이은~이어 끝없이 늘인] 선이에요.","ex":"선분 ㄱㄴ: 점 ㄱ에서 점 ㄴ까지","x":"선분은 끝이 없어요.","why":"선분은 양 끝 두 점이 있어서 길이를 잴 수 있어요.","fig":"lineseg","ln":["선","직선"]},{"w":"반직선","en":"half line","d":"한 점에서 시작해 [한쪽으로만 끝없이~양쪽으로~조금만] 뻗은 곧은 선이에요.","ex":"반직선 AB: A에서 시작해 B 쪽으로 끝없이","x":"반직선 AB와 반직선 BA는 같아요.","why":"시작점과 방향이 달라서 서로 다른 반직선이에요.","fig":"lineseg","ln":["직선","선분"]}]},{"n":"각","id":"shape-angle","t":[{"w":"각","en":"angle","d":"한 점에서 그은 [두 반직선이 이루는~두 원이 만나는~세 점을 이은] 도형이에요.","ex":"각 ㄱㄴㄷ (꼭짓점은 ㄴ)","x":"각의 변을 길게 그리면 각이 더 커져요.","why":"각의 크기는 두 변이 벌어진 정도예요. 변의 길이와는 상관없어요.","fig":"ang","ln":["각도"]},{"w":"꼭짓점","en":"vertex","d":"두 개 이상의 [선이나 모서리가 만나는~면이 넓은~가운데 있는] 점이에요.","ex":"삼각형의 꼭짓점 3개","x":"원에는 꼭짓점이 1개 있어요.","why":"원은 곧은 변이 만나지 않아서 꼭짓점이 없어요.","fig":"tri","ln":["각","모서리"]},{"w":"변","en":"side","d":"다각형을 [이루는 선분~안쪽 넓이~꼭짓점]이에요.","ex":"삼각형의 변 3개","x":"변은 굽은 선이어도 돼요.","why":"다각형의 변은 모두 곧은 선분이에요.","fig":"tri","ln":["다각형","선분","모서리"]},{"w":"각도","en":"angle measure","d":"각의 [크기~변의 길이~넓이]예요. 단위는 도(°)이고, 직각은 90°예요.","ex":"직각 90°, 한 바퀴 360°","x":"각도는 cm로 재요.","why":"각도는 각도기로 재고 단위는 도(°)예요.","fig":"ang","ln":["각","각도기"]},{"w":"각도기","en":"protractor","d":"[각의 크기를 재는~길이를 재는~원을 그리는] 도구예요.","ex":"반원 모양, 작은 눈금 하나가 1°","x":"각도기는 아무 데나 대고 읽어도 돼요.","why":"각도기 중심을 꼭짓점에, 밑금을 한 변에 맞춰야 해요.","fig":"prot","ln":["각"]},{"w":"직각","en":"right angle","d":"[90°인~180°인~45°인] 각이에요.","ex":"종이를 반으로 두 번 접으면 생기는 각","x":"직각은 100°예요.","why":"직각은 정확히 90°예요.","fig":"ang90","ln":["예각","둔각","평각"]},{"w":"예각","en":"acute angle","d":"0°보다 크고 [90°보다 작은~90°보다 큰~180°인] 각이에요.","ex":"30°, 60°","x":"90°도 예각이에요.","why":"90°는 직각이에요. 예각은 90°보다 작아야 해요.","fig":"ang60","ln":["직각","둔각","예각삼각형"]},{"w":"둔각","en":"obtuse angle","d":"[90°보다 크고 180°보다 작은~90°보다 작은~딱 90°인] 각이에요.","ex":"120°, 150°","x":"200°는 둔각이에요.","why":"둔각은 180°보다 작아야 해요.","fig":"ang120","ln":["각","예각","직각"]},{"w":"평각","en":"straight angle","d":"두 반직선이 [일직선을~직각을~한 점을] 이룰 때의 각이에요. 180°예요.","ex":"직각 2개 = 평각 180°","x":"평각은 각이 아니에요.","why":"일직선이어도 꼭짓점과 두 변이 있어서 180°짜리 각이에요.","fig":"ang180","ln":["직각","각"]}]},{"n":"선과 선","id":"shape-lines2","t":[{"w":"수직","en":"perpendicular","d":"두 직선이 만나서 [직각을~예각을~평행을] 이루는 상태예요.","ex":"교실 벽과 바닥","x":"비스듬히 만나도 수직이에요.","why":"직각(90°)으로 만날 때만 수직이에요.","fig":"perp","ln":["직각"]},{"w":"수선","en":"perpendicular line","d":"한 직선에 [수직인~평행인~비스듬한] 직선이에요.","ex":"가로선에 세워 그은 직각 선","x":"수선은 늘 세로로 그은 선이에요.","why":"어느 방향이든 다른 직선과 직각으로 만나면 수선이에요.","fig":"perp","ln":["직각","수직"]},{"w":"평행","en":"parallel","d":"두 직선이 [아무리 늘여도 만나지 않는~한 점에서 만나는~직각으로 만나는] 상태예요.","ex":"기찻길 두 레일","x":"길이가 다르면 평행할 수 없어요.","why":"길이와 상관없이 끝까지 늘여도 만나지 않으면 평행이에요.","fig":"par","ln":["평행선","평행사변형"]},{"w":"평행선","en":"parallel lines","d":"[서로 평행한~서로 수직인~한 점에서 만나는] 두 직선이에요.","ex":"공책의 줄","x":"평행선은 언젠가 만나요.","why":"평행선은 아무리 늘여도 만나지 않아요.","fig":"par","ln":["평행"]},{"w":"평행선 사이의 거리","en":"distance between parallel lines","d":"평행선의 한 직선에서 다른 직선에 [수직으로 그은 선분의 길이~비스듬히 그은 선분의 길이~두 선의 길이 합]예요.","ex":"사다리 가로대 사이 거리","x":"평행선 사이에 아무렇게나 그은 선분이 모두 거리예요.","why":"수직인 선분이 가장 짧고, 그 길이가 거리예요.","fig":"par","ln":["평행선"]},{"w":"교점","en":"point of intersection","d":"선과 선, 선과 면이 [만나서 생기는 점~떨어져 있는 점~끝점]이에요.","ex":"X자 두 선이 만나는 점","x":"평행선에도 교점이 있어요.","why":"평행선은 만나지 않아서 교점이 없어요.","fig":"cross","ln":["교각","교선"]},{"w":"교각","en":"angle of intersection","d":"두 직선이 만나서 생기는 [각~점~선]이에요. 두 직선이 만나면 교각이 4개 생겨요.","ex":"X자에서 생기는 4개의 각","x":"두 직선이 만나면 교각은 2개예요.","why":"두 직선이 만나면 교각이 4개 생겨요.","fig":"cross","ln":["교선","교점"]},{"w":"맞꼭지각","en":"vertically opposite angles","d":"두 직선이 만날 때 [서로 마주 보는~서로 붙어 있는~한 직선 위의] 각이에요. 크기가 같아요.","ex":"X자의 위아래 각, 왼쪽 오른쪽 각","x":"맞꼭지각은 두 각의 크기가 서로 달라요.","why":"맞꼭지각은 늘 크기가 같아요. 더해서 180°가 되는 건 붙어 있는 두 각이에요.","fig":"cross","ln":["각","엇각","동위각"]},{"w":"동위각","en":"corresponding angles","d":"두 직선이 다른 한 직선과 만날 때 [같은 위치에 있는~엇갈린 위치의~마주 보는] 각이에요.","ex":"두 평행선을 가로지르는 선에서 위쪽 오른쪽 각끼리","x":"동위각은 언제나 크기가 같아요.","why":"두 직선이 평행할 때만 동위각의 크기가 같아요.","fig":"trans","ln":["엇각"]},{"w":"엇각","en":"alternate angles","d":"두 직선이 다른 한 직선과 만날 때 [엇갈린 위치에 있는~같은 위치에 있는~이웃한] 각이에요.","ex":"Z자 모양 안쪽의 두 각","x":"엇각은 언제나 크기가 같아요.","why":"두 직선이 평행할 때만 엇각의 크기가 같아요.","fig":"trans","ln":["각"]},{"w":"이등분하다","en":"bisect","d":"[똑같이 둘로~셋으로~아무렇게나] 나누는 것이에요.","ex":"사과를 이등분하면 1/2씩","x":"이등분하면 조각 크기가 달라도 돼요.","why":"이등분은 똑같이 둘로 나눠야 해요.","ln":["합동"]},{"w":"중점","en":"midpoint","d":"선분을 [이등분하는 점~삼등분하는 점~끝점]이에요.","ex":"선분 AB의 중점 O: AO = OB","x":"중점은 선분 위 아무 점이에요.","why":"중점은 두 끝에서 거리가 똑같은 한가운데 점이에요.","fig":"mid","ln":["이등분하다"]},{"w":"수직이등분선","en":"perpendicular bisector","d":"선분의 [중점을 지나고 수직인~끝점을 지나는~평행한] 직선이에요.","ex":"선분 AB를 직각으로 반 가르는 선","x":"중점을 지나기만 하면 수직이등분선이에요.","why":"중점을 지나면서 선분과 수직이어야 해요.","fig":"mid","ln":["수직","중점","이등분하다"]},{"w":"각의 이등분선","en":"angle bisector","d":"각을 [똑같은 크기의 두 각으로~크기가 다른 두 각으로~세 각으로] 나누는 반직선이에요.","ex":"60°를 30°와 30°로 나누는 선","x":"각의 이등분선은 각을 아무렇게나 둘로 나눠요.","why":"두 각의 크기가 같아야 이등분선이에요.","ln":["수직이등분선"]}]},{"n":"도형의 기본","id":"shape-base","t":[{"w":"도형","en":"figure","d":"점, 선, 면으로 [만들어진 모양~이루어진 수~정한 약속]이에요.","ex":"삼각형, 원, 정육면체","x":"도형은 종이 위에 그린 것만 말해요.","why":"공 같은 입체도형도 도형이에요.","ln":["평면도형","입체도형"]},{"w":"모양","en":"shape","d":"겉으로 보이는 [생김새~무게~값]예요.","ex":"세모, 네모, 동그라미 모양","x":"모양이 같으면 크기도 같아요.","why":"모양이 같아도 크기는 다를 수 있어요.","ln":["도형"]},{"w":"평면도형","en":"plane figure","d":"[평평한 면 위에 그릴 수 있는~공간을 차지하는~부피가 있는] 도형이에요.","ex":"삼각형, 사각형, 원","x":"평면도형에도 부피가 있어요.","why":"평면도형은 넓이는 있지만 부피는 없어요.","ln":["변","입체도형"]},{"w":"입체도형","en":"solid figure","d":"[공간에서 부피를 가진~종이 위에만 있는~선으로만 된] 도형이에요.","ex":"상자, 공, 깡통","x":"입체도형은 평면 위에 그릴 수 없어요.","why":"겨냥도처럼 입체도형을 평면에 그려 나타낼 수 있어요. 하지만 입체도형 자체는 부피가 있어요.","fig":"cube","ln":["평면도형"]},{"w":"다각형","en":"polygon","d":"[선분으로만 둘러싸인~곡선으로 둘러싸인~열려 있는] 평면도형이에요.","ex":"삼각형, 사각형, 오각형","x":"원도 다각형이에요.","why":"원은 곡선이라 다각형이 아니에요.","fig":"polys","ln":["평면도형"]},{"w":"대각선","en":"diagonal","d":"다각형에서 [이웃하지 않는 두 꼭짓점을 이은~이웃한 두 꼭짓점을 이은~꼭짓점과 변을 이은] 선분이에요.","ex":"사각형의 대각선 2개","x":"삼각형에는 대각선이 3개 있어요.","why":"삼각형은 모든 꼭짓점이 서로 이웃해서 대각선이 없어요.","fig":"diag","ln":["꼭짓점"]},{"w":"내각","en":"interior angle","d":"다각형의 [안쪽에 있는~바깥에 있는~가운데 있는] 각이에요.","ex":"삼각형 내각의 합 180°, 사각형 내각의 합 360°","x":"큰 삼각형은 내각의 합도 커요.","why":"삼각형이면 크기와 상관없이 내각의 합은 180°예요.","fig":"tri","ln":["외각"]},{"w":"외각","en":"exterior angle","d":"다각형의 한 변과 [이웃한 변을 늘인 선이 이루는~마주 보는 변이 이루는~대각선이 이루는] 각이에요.","ex":"삼각형 외각의 합 360°","x":"내각과 외각을 더하면 360°예요.","why":"한 꼭짓점에서 내각 + 외각 = 180°예요.","ln":["각","내각"]},{"w":"마주 보다","en":"face each other","d":"도형에서 서로 [대응하거나 맞은편에 있는~바로 붙어 있는~겹쳐 있는] 것을 말해요.","ex":"직사각형의 마주 보는 변은 길이가 같아요.","x":"사각형에서 마주 보는 변은 서로 붙어 있어요.","why":"마주 보는 변은 맞은편에 있어서 서로 만나지 않아요.","fig":"rect","ln":["대응"]},{"w":"대각","en":"opposite angle","d":"다각형에서 [한 변이나 한 각과 마주 보는~바로 옆에 있는~바깥에 있는] 각이에요.","ex":"평행사변형의 대각은 크기가 같아요.","x":"대각은 바로 옆에 붙은 각이에요.","why":"대각은 맞은편에 있는 각이에요.","ln":["변","각"]}]},{"n":"삼각형","id":"shape-tri","t":[{"w":"삼각형","en":"triangle","d":"[3개의 선분~4개의 선분~곡선 하나]으로 둘러싸인 도형이에요. 변·꼭짓점·각이 3개씩이에요.","ex":"세 각의 합은 늘 180°","x":"세 변 중 하나가 굽어 있어도 삼각형이에요.","why":"세 변이 모두 곧은 선분이어야 삼각형이에요.","fig":"tri","ln":["예각삼각형","둔각삼각형","직각삼각형"]},{"w":"직각삼각형","en":"right triangle","d":"한 각이 [직각인~둔각인~모두 예각인] 삼각형이에요.","ex":"삼각자","x":"직각삼각형에는 직각이 2개 있을 수 있어요.","why":"세 각의 합이 180°라 직각은 하나뿐이에요.","fig":"trir","ln":["예각삼각형","둔각삼각형"]},{"w":"예각삼각형","en":"acute triangle","d":"세 각이 [모두 예각인~하나만 예각인~모두 직각인] 삼각형이에요.","ex":"세 각이 70°, 60°, 50°인 삼각형","x":"예각이 2개 있으면 예각삼각형이에요.","why":"모든 삼각형에 예각은 2개 이상 있어요. 세 각 모두 예각이어야 해요.","fig":"tria","ln":["예각","둔각삼각형"]},{"w":"둔각삼각형","en":"obtuse triangle","d":"한 각이 [둔각인~직각인~예각인] 삼각형이에요.","ex":"세 각이 120°, 40°, 20°인 삼각형","x":"둔각삼각형에는 둔각이 2개 있어요.","why":"둔각 두 개면 합이 180°를 넘어서 둔각은 하나뿐이에요.","fig":"trio","ln":["예각삼각형","직각삼각형"]},{"w":"이등변삼각형","en":"isosceles triangle","d":"[두 변의 길이가 같은~세 변이 모두 다른~한 각이 직각인] 삼각형이에요. 두 밑각도 같아요.","ex":"두 변이 5cm, 5cm인 삼각형","x":"정삼각형은 이등변삼각형이 아니에요.","why":"정삼각형도 두 변이 같으니 이등변삼각형이라 할 수 있어요.","fig":"trii","ln":["정삼각형","밑각"]},{"w":"정삼각형","en":"equilateral triangle","d":"[세 변의 길이가 모두 같은~두 변만 같은~한 각이 90°인] 삼각형이에요. 세 각은 모두 60°예요.","ex":"세 변이 4cm씩","x":"정삼각형의 한 각은 90°예요.","why":"180° ÷ 3 = 60°예요.","fig":"trie","ln":["정다각형","삼각형"]},{"w":"밑변","en":"base","d":"도형에서 [아래쪽에 놓여 높이의 기준이 되는~가장 긴~비스듬한] 변이에요.","ex":"삼각형을 놓은 아래 변","x":"밑변은 늘 맨 아래 있는 변 하나로 정해져 있어요.","why":"높이를 어디서 재느냐에 따라 어느 변이든 밑변이 될 수 있어요.","fig":"trih","ln":["평면도형"]},{"w":"높이","en":"height","d":"밑변에서 마주 보는 꼭짓점이나 변까지 [수직으로 잰~비스듬히 잰~빙 돌아 잰] 거리예요.","ex":"삼각형 꼭대기에서 밑변까지 직각으로 잰 길이 4cm","x":"비스듬한 변의 길이가 높이예요.","why":"높이는 밑변과 수직인 길이예요.","fig":"trih","ln":["길이","각뿔의 높이"]},{"w":"밑각","en":"base angle","d":"[밑변의 양 끝에 있는~꼭대기에 있는~바깥에 있는] 각이에요.","ex":"이등변삼각형의 두 밑각은 크기가 같아요.","x":"밑각은 꼭대기 각이에요.","why":"밑변 양 끝의 두 각이 밑각이에요.","fig":"trii","ln":["각"]},{"w":"빗변","en":"hypotenuse","d":"직각삼각형에서 [직각과 마주 보는~직각에 붙은~가장 짧은] 변이에요. 가장 길어요.","ex":"삼각자의 비스듬한 긴 변","x":"빗변은 직각삼각형에서 가장 짧은 변이에요.","why":"빗변은 가장 긴 변이에요.","fig":"trir","ln":["직각삼각형"]},{"w":"삼각형의 결정 조건","en":"conditions for a triangle","d":"삼각형 하나를 [딱 하나로 정할 수 있는~여러 개 그리는~못 그리는] 조건이에요.","ex":"①세 변의 길이 ②두 변과 그 사이 각 ③한 변과 양 끝 각","x":"세 각의 크기만 알아도 삼각형이 하나로 정해져요.","why":"세 각만 같으면 크기가 다른 삼각형이 많이 생겨요.","ln":["삼각형"]}]},{"n":"사각형","id":"shape-quad","t":[{"w":"사각형","en":"quadrilateral","d":"[4개의 선분~3개의 선분~5개의 선분]으로 둘러싸인 도형이에요.","ex":"사다리꼴, 마름모, 직사각형","x":"네 각의 합은 180°예요.","why":"사각형 네 각의 합은 360°예요.","fig":"quad","ln":["평면도형","다각형"]},{"w":"사다리꼴","en":"trapezoid","d":"[마주 보는 한 쌍의 변이 평행한~평행한 변이 없는~네 변이 같은] 사각형이에요.","ex":"사다리 옆모습","x":"평행사변형은 사다리꼴이 아니에요.","why":"평행한 변이 한 쌍이라도 있으면 사다리꼴이라, 평행사변형도 사다리꼴이에요.","fig":"trap","ln":["사각형"]},{"w":"평행사변형","en":"parallelogram","d":"[마주 보는 두 쌍의 변이 모두 평행한~한 쌍만 평행한~평행한 변이 없는] 사각형이에요.","ex":"마주 보는 변과 각의 크기가 같아요.","x":"직사각형은 평행사변형이 아니에요.","why":"직사각형도 두 쌍이 평행해서 평행사변형이에요.","fig":"para","ln":["평행","마주 보다"]},{"w":"마름모","en":"rhombus","d":"[네 변의 길이가 모두 같은~네 각이 모두 직각인~한 쌍만 평행한] 사각형이에요.","ex":"두 대각선이 서로 수직으로 반을 나눠요.","x":"마름모는 네 각이 모두 같아야 해요.","why":"마름모는 네 변이 같으면 돼요. 각까지 같으면 정사각형이에요.","fig":"rhom","ln":["사각형","정사각형"]},{"w":"직사각형","en":"rectangle","d":"[네 각이 모두 직각인~네 변이 모두 같은~한 각만 직각인] 사각형이에요.","ex":"교과서, 문","x":"정사각형은 직사각형이 아니에요.","why":"정사각형도 네 각이 직각이라 직사각형이에요.","fig":"rect","ln":["사각형","정사각형"]},{"w":"정사각형","en":"square","d":"[네 변이 같고 네 각이 모두 직각인~네 변만 같은~네 각만 직각인] 사각형이에요.","ex":"바둑판 한 칸","x":"정사각형은 마름모가 아니에요.","why":"네 변이 같으니 마름모이기도 해요.","fig":"sq","ln":["정다각형","사각형"]}]},{"n":"여러 가지 다각형","id":"shape-poly","t":[{"w":"오각형","en":"pentagon","d":"[5개의 선분~6개의 선분~5개의 곡선]으로 둘러싸인 도형이에요.","ex":"꼭짓점 5개, 변 5개","x":"오각형은 변이 6개예요.","why":"이름 '오(5)'처럼 변이 5개예요.","fig":"pent","ln":["다각형"]},{"w":"육각형","en":"hexagon","d":"[6개의 선분~5개의 선분~8개의 선분]으로 둘러싸인 도형이에요.","ex":"벌집 한 칸","x":"육각형의 꼭짓점은 5개예요.","why":"변이 6개면 꼭짓점도 6개예요.","fig":"hex","ln":["정육각형","다각형"]},{"w":"정다각형","en":"regular polygon","d":"[변의 길이와 각의 크기가 모두 같은~변만 같은~각만 같은] 다각형이에요.","ex":"정삼각형, 정사각형, 정오각형","x":"변의 길이만 같으면 정다각형이에요.","why":"마름모처럼 변만 같고 각이 다르면 정다각형이 아니에요.","fig":"polys","ln":["정삼각형","정사각형","정오각형","정육각형"]},{"w":"정오각형","en":"regular pentagon","d":"다섯 변과 다섯 각이 [모두 같은~하나만 다른~모두 다른] 오각형이에요. 한 각은 108°예요.","ex":"축구공 검은 조각","x":"정오각형의 한 각은 90°예요.","why":"정오각형 각의 합 540° ÷ 5 = 108°예요.","fig":"pent","ln":["정다각형","오각형"]},{"w":"정육각형","en":"regular hexagon","d":"여섯 변과 여섯 각이 [모두 같은~둘만 같은~모두 다른] 육각형이에요. 한 각은 120°예요.","ex":"벌집 모양","x":"정육각형의 한 각은 60°예요.","why":"정육각형 각의 합 720° ÷ 6 = 120°예요.","fig":"hex","ln":["정다각형"]},{"w":"칠교","en":"tangram","d":"정사각형을 [일곱 조각으로 잘라~다섯 조각으로 잘라~두 조각으로 잘라] 여러 모양을 만드는 놀이예요.","ex":"큰 삼각형 2, 중간 1, 작은 2, 정사각형 1, 평행사변형 1","x":"칠교 조각은 모두 삼각형이에요.","why":"정사각형 1개, 평행사변형 1개도 있어요.","fig":"tangram","ln":["삼각형","평행사변형","정사각형"]},{"w":"펜토미노","en":"pentomino","d":"[정사각형 5개~정사각형 4개~삼각형 5개]를 변끼리 붙여 만든 모양이에요. 모두 12가지예요.","ex":"L자, T자, 십자 모양","x":"꼭짓점만 붙여도 펜토미노예요.","why":"변과 변이 꼭 맞게 붙어야 해요.","fig":"pento","ln":["정사각형"]},{"w":"도미노","en":"domino","d":"[정사각형 2개~정사각형 3개~삼각형 2개]를 붙인 직사각형 조각이에요.","ex":"점이 찍힌 도미노 패","x":"도미노 조각은 정사각형이에요.","why":"정사각형 두 개를 붙인 직사각형이에요.","ln":["정사각형"]},{"w":"테셀레이션","en":"tessellation","d":"같은 도형을 [빈틈없이, 겹치지 않게~겹치게~띄엄띄엄] 이어 붙여 평면을 덮는 것이에요.","ex":"욕실 타일, 벌집","x":"정오각형만으로도 테셀레이션을 할 수 있어요.","why":"정오각형은 한 점에 모인 각이 360°가 안 맞아 틈이 생겨요.","fig":"tess","ln":["도형 돌리기","도형 뒤집기","도형 밀기"]}]},{"n":"원","id":"shape-circle","t":[{"w":"원","en":"circle","d":"한 점에서 [같은 거리에 있는 점들~다른 거리에 있는 점들~가장 먼 점]을 이은 도형이에요.","ex":"동전, 바퀴","x":"원에는 꼭짓점이 있어요.","why":"원은 곧은 변이 없어서 꼭짓점도 없어요.","fig":"circ","ln":["원의 중심","원의 지름","원의 넓이"]},{"w":"원의 중심","en":"center of a circle","d":"원을 그릴 때 기준이 된 점, [원 위의 모든 점에서 같은 거리에 있는~원 위에 있는~원 밖에 있는] 점이에요.","ex":"컴퍼스 침을 꽂은 점","x":"원의 중심은 원 위에 있어요.","why":"원의 중심은 원 안쪽 한가운데에 있어요.","fig":"circ","ln":["원","반지름"]},{"w":"반지름","en":"radius","d":"원의 중심과 [원 위의 한 점을 이은~원 위의 두 점을 이은~원 밖의 점을 이은] 선분이에요.","ex":"한 원에서 반지름은 모두 길이가 같아요.","x":"한 원의 반지름은 길이가 저마다 달라요.","why":"한 원에서 반지름은 무수히 많고 길이가 모두 같아요.","fig":"circ","ln":["지름","원","구(공)"]},{"w":"원의 지름","en":"diameter","d":"원 위의 두 점을 이은 선분 중 [원의 중심을 지나는~중심을 지나지 않는~가장 짧은] 것이에요.","ex":"지름 = 반지름 × 2","x":"지름은 반지름의 반이에요.","why":"지름은 반지름의 2배예요.","fig":"circ","ln":["원","원의 중심"]},{"w":"지름","en":"diameter","d":"원의 지름을 줄여 부르는 말로, [원에서 가장 긴 현~원에서 가장 짧은 현~원 밖의 선]이에요.","ex":"반지름 3cm인 원의 지름 6cm","x":"지름보다 긴 현도 있어요.","why":"원 안에 그을 수 있는 선분 중 지름이 가장 길어요.","fig":"circ","ln":["원","현"]},{"w":"원주","en":"circumference","d":"[원의 둘레~원의 넓이~원의 지름]예요.","ex":"원주 = 지름 × 원주율","x":"원주는 지름과 길이가 같아요.","why":"원주는 지름의 약 3.14배예요.","fig":"circ","ln":["원주율"]},{"w":"원주율","en":"pi","d":"[원주를 지름으로 나눈~지름을 원주로 나눈~반지름을 더한] 값이에요. 약 3.14이고 π로 써요.","ex":"원의 크기와 상관없이 늘 약 3.14","x":"큰 원일수록 원주율이 커요.","why":"원주율은 모든 원에서 같아요.","fig":"circ","ln":["원주","원"]},{"w":"호","en":"arc","d":"원 위의 두 점 사이의 [원의 일부분(곡선)~곧은 선분~중심까지 선]이에요.","ex":"원 위의 두 점 A, B 사이에 휘어진 부분(⌒AB)","x":"호는 곧은 선분이에요.","why":"호는 원의 둘레 일부라 휘어 있어요. 곧은 건 현이에요.","fig":"arc","ln":["원","현"]},{"w":"현","en":"chord","d":"원 위의 두 점을 [곧게 이은 선분~휘어지게 이은 선~중심과 이은 선]이에요.","ex":"가장 긴 현이 지름","x":"현은 반드시 원의 중심을 지나요.","why":"중심을 지나는 현만 지름이에요. 대부분의 현은 중심을 지나지 않아요.","fig":"arc","ln":["호","지름"]},{"w":"부채꼴","en":"sector","d":"원에서 [두 반지름과 호로 둘러싸인~두 현으로 둘러싸인~지름 하나로 나뉜] 부분이에요.","ex":"부채, 피자 한 조각","x":"부채꼴은 두 현과 호로 만들어요.","why":"부채꼴은 두 반지름과 호로 둘러싸여요.","fig":"sector","ln":["원","중심각","반지름"]},{"w":"중심각","en":"central angle","d":"부채꼴에서 [두 반지름이 이루는~두 현이 이루는~호와 반지름이 이루는] 각이에요.","ex":"피자 한 조각 끝 뾰족한 각","x":"중심각은 원 위의 점에 있어요.","why":"중심각의 꼭짓점은 원의 중심이에요.","fig":"sector","ln":["부채꼴"]},{"w":"타원","en":"ellipse","d":"[원을 한쪽으로 납작하게 누른 것 같은~네모난~뾰족한] 곡선 도형이에요.","ex":"원기둥을 비스듬히 자른 단면","x":"타원도 원이에요.","why":"타원은 중심에서 둘레까지 거리가 곳마다 달라서 원이 아니에요.","fig":"ellipse","ln":["원","대칭축"]},{"w":"컴퍼스","en":"compass","d":"[원을 그리거나 길이를 옮기는~각도를 재는~직선을 긋는] 도구예요.","ex":"두 다리를 반지름만큼 벌려 돌려요.","x":"컴퍼스로 각도를 재요.","why":"각도는 각도기로 재요. 컴퍼스는 원과 길이 옮기기예요.","ln":["작도"]},{"w":"작도","en":"construction","d":"[눈금 없는 자와 컴퍼스만으로~각도기로~손으로 대충] 도형을 그리는 것이에요.","ex":"정삼각형 작도","x":"작도할 때는 자의 눈금으로 길이를 재요.","why":"작도에서는 눈금을 쓰지 않고 컴퍼스로 길이를 옮겨요.","ln":["컴퍼스","자"]}]},{"n":"합동과 닮음","id":"shape-cong","t":[{"w":"겹치다","en":"overlap","d":"한 도형을 다른 도형 [위에 포개어 놓는~옆에 붙여 놓는~멀리 놓는] 것이에요.","ex":"두 삼각형을 겹쳐 보기","x":"겹쳐서 일부만 맞으면 합동이에요.","why":"완전히 포개어질 때만 합동이에요.","ln":["합동"]},{"w":"합동","en":"congruence","d":"[모양과 크기가 같아서 완전히 겹쳐지는~모양만 같은~색이 같은] 두 도형의 관계예요.","ex":"같은 틀로 찍은 쿠키","x":"모양이 같으면 크기가 달라도 합동이에요.","why":"크기까지 같아야 합동이에요. 모양만 같으면 닮음이에요.","fig":"cong","ln":["도형 밀기"]},{"w":"대응","en":"correspondence","d":"두 도형이나 묶음에서 [짝을 이루는~아무 관계 없는~크기가 다른] 것이에요.","ex":"합동인 두 삼각형에서 짝이 되는 꼭짓점, 변, 각","x":"대응하는 변은 길이가 달라요.","why":"합동이면 대응하는 변의 길이와 각의 크기가 같아요.","fig":"cong","ln":["합동"]},{"w":"삼각형의 합동 조건","en":"congruence conditions","d":"두 삼각형이 [합동임을 알 수 있는~닮음임을 알 수 있는~못 그리는] 세 가지 조건이에요.","ex":"①세 변(SSS) ②두 변과 끼인각(SAS) ③한 변과 양 끝 각(ASA)","x":"세 각이 같으면 두 삼각형은 합동이에요.","why":"세 각만 같으면 크기가 달라도 되니 합동이 아니라 닮음이에요.","ln":["삼각형","합동"]},{"w":"닮은 도형","en":"similar figures","d":"[모양은 같고 크기만 다를 수 있는~모양이 다른~색만 같은] 도형이에요.","ex":"크기가 다른 두 정사각형","x":"모든 직사각형은 서로 닮은 도형이에요.","why":"가로세로 비율이 다르면 직사각형끼리도 닮지 않아요.","fig":"sim","ln":["닮음비","합동"]},{"w":"닮음비","en":"similarity ratio","d":"닮은 도형에서 [대응하는 변의 길이의 비~넓이의 합~각의 합]예요.","ex":"변이 2cm, 4cm면 닮음비 1 : 2","x":"닮음비가 1 : 1이면 크기가 달라요.","why":"닮음비 1 : 1이면 크기가 같아서 합동이에요.","fig":"sim","ln":["닮은 도형","대응","합동"]}]},{"n":"도형 움직이기","id":"shape-move","t":[{"w":"도형 밀기","en":"slide","d":"도형을 [어느 방향으로 미는~뒤집는~돌리는] 것이에요. 모양과 크기는 그대로예요.","ex":"종이비행기를 오른쪽으로 쭉 밀기","x":"밀면 도형이 뒤집혀요.","why":"밀기는 위치만 바뀌고 방향은 그대로예요.","fig":"slide","ln":["테셀레이션"]},{"w":"도형 뒤집기","en":"flip","d":"[한 직선을 기준으로~한 점을 기준으로 빙글~위치만] 도형을 뒤집는 것이에요. 좌우나 위아래가 바뀌어요.","ex":"거울에 비친 모습","x":"오른쪽으로 뒤집어도 왼쪽과 오른쪽은 그대로예요.","why":"뒤집으면 왼쪽과 오른쪽이 서로 바뀌어요.","fig":"flip","ln":["대칭축","테셀레이션"]},{"w":"도형 돌리기","en":"turn","d":"도형을 [한 점을 중심으로~한 직선을 기준으로~밀어서] 돌리는 것이에요.","ex":"시계 방향으로 90° 돌리기","x":"돌리면 도형의 크기가 바뀌어요.","why":"돌려도 모양과 크기는 그대로예요.","fig":"turn","ln":["점대칭 도형","테셀레이션"]},{"w":"회전","en":"rotation","d":"도형이 한 점이나 축을 [중심으로 도는~따라 미는~기준으로 뒤집는] 것이에요.","ex":"팽이, 대관람차","x":"회전하면 도형의 모양이 바뀌어요.","why":"회전은 위치와 방향만 바뀌어요.","fig":"turn","ln":["회전체"]},{"w":"시계 방향","en":"clockwise","d":"[시계 바늘이 도는~시계 바늘과 반대로 도는~위아래로 움직이는] 방향이에요.","ex":"오른쪽으로 빙글","x":"시계 방향은 왼쪽으로 도는 거예요.","why":"시계 바늘은 위에서 오른쪽으로 돌아요.","fig":"turn","ln":["반시계 방향"]},{"w":"반시계 방향","en":"counterclockwise","d":"시계 바늘이 도는 방향의 [반대~같은~위아래] 방향이에요.","ex":"왼쪽으로 빙글","x":"반시계 방향과 시계 방향은 같아요.","why":"서로 반대 방향이에요.","fig":"turn","ln":["시계 방향"]},{"w":"대칭이동","en":"reflection move","d":"도형을 [대칭축이나 대칭의 중심을 기준으로~아무 데로나~크게 늘여서] 옮기는 것이에요.","ex":"종이를 접어 반대편에 찍기","x":"대칭이동하면 크기가 커져요.","why":"모양과 크기는 그대로예요.","fig":"flip","ln":["대칭축","대칭의 중심"]},{"w":"반사","en":"reflection","d":"빛이나 파동이 다른 물체에 [부딪혀 방향을 바꾸는~통과하는~사라지는] 현상이에요.","ex":"거울에 비친 내 모습","x":"거울에 비친 모습은 좌우가 그대로예요.","why":"거울 속은 좌우가 바뀌어 보여요(선대칭).","fig":"flip","ln":["선대칭 도형"]}]},{"n":"대칭","id":"shape-sym","t":[{"w":"대칭","en":"symmetry","d":"[한 점이나 직선을 기준으로 마주 보는~아무렇게나 놓인~크기가 다른] 모양이 같은 것이에요.","ex":"나비 날개","x":"대칭은 두 부분의 크기가 달라도 돼요.","why":"기준 양쪽이 크기와 모양 모두 같아야 해요.","fig":"symline","ln":["선대칭 도형","점대칭 도형","대칭축"]},{"w":"대칭축","en":"axis of symmetry","d":"[접었을 때 완전히 겹치게 하는~도형을 돌리는~도형을 미는] 직선이에요.","ex":"하트 모양의 세로 가운데 선","x":"정사각형의 대칭축은 2개예요.","why":"정사각형은 가로, 세로, 대각선 2개로 대칭축이 4개예요.","fig":"symline","ln":["점대칭 도형","선대칭 도형"]},{"w":"선대칭 도형","en":"line-symmetric figure","d":"[한 직선으로 접으면 완전히 겹치는~한 점으로 돌리면 겹치는~접어도 안 겹치는] 도형이에요.","ex":"하트, 정삼각형","x":"모든 평행사변형은 선대칭 도형이에요.","why":"보통의 평행사변형은 어디로 접어도 완전히 겹치지 않아요(직사각형·마름모는 예외).","fig":"symline","ln":["선대칭 위치에 있는 도형","대칭축"]},{"w":"선대칭 위치에 있는 도형","en":"figures in line symmetry","d":"[한 직선을 사이에 두고 접으면 겹치는~한 점을 중심으로 돌리면 겹치는~나란히 놓인] 두 도형이에요.","ex":"데칼코마니 양쪽 그림","x":"선대칭 위치에 있는 두 도형은 크기가 달라요.","why":"접어서 완전히 겹치니 모양과 크기가 같아요.","fig":"flip","ln":["선대칭 도형","대칭축"]},{"w":"대칭의 중심","en":"center of symmetry","d":"도형을 [180° 돌렸을 때 처음과 겹치게 하는~반으로 접는~옆으로 미는] 중심 점이에요.","ex":"평행사변형의 두 대각선이 만나는 점","x":"점대칭 도형의 대칭의 중심은 도형 밖에 있어요.","why":"점대칭 도형의 대칭의 중심은 한가운데에 있어요.","fig":"pointsym","ln":["대칭"]},{"w":"점대칭 도형","en":"point-symmetric figure","d":"한 점을 중심으로 [180° 돌렸을 때~90° 돌렸을 때~접었을 때] 처음과 완전히 겹치는 도형이에요.","ex":"평행사변형, S 글자","x":"정삼각형은 점대칭 도형이에요.","why":"정삼각형은 180° 돌리면 거꾸로 서서 겹치지 않아요.","fig":"pointsym","ln":["점대칭 위치에 있는 도형","대칭의 중심"]},{"w":"점대칭 위치에 있는 도형","en":"figures in point symmetry","d":"한 점을 중심으로 [180° 돌렸을 때 겹치는~접었을 때 겹치는~밀었을 때 겹치는] 두 도형이에요.","ex":"트럼프 카드에 위아래 거꾸로 그려진 두 그림","x":"점대칭 위치는 직선으로 접어서 확인해요.","why":"점을 중심으로 180° 돌려서 확인해요.","fig":"pointsym","ln":["점대칭 도형","대칭의 중심"]},{"w":"축","en":"axis","d":"무엇의 [중심이나 기준이 되는 선~끝점~넓이]이에요.","ex":"지구의 자전축, 대칭축, 가로축","x":"축은 언제나 세로선이에요.","why":"가로축처럼 가로선일 수도 있어요.","ln":["대칭축"]}]},{"n":"입체도형의 부분","id":"shape-solidpart","t":[{"w":"면","en":"face","d":"입체도형의 겉을 이루는 [평평하거나 굽은 부분~가장자리 선~뾰족한 점]이에요.","ex":"정육면체의 면 6개, 공의 면 1개","x":"공에는 면이 없어요.","why":"공은 굽은 면(곡면)이 1개 있어요.","fig":"cube","ln":["선","평면"]},{"w":"평면","en":"plane","d":"[어느 두 점을 이은 직선도 그 위에 놓이는 평평한~울퉁불퉁한~둥근] 면이에요.","ex":"책상 윗면","x":"평면은 휘어 있어요.","why":"평면은 평평한 면이에요. 휜 면은 곡면이에요.","ln":["수평"]},{"w":"곡면","en":"curved surface","d":"[부드럽게 휘어진~평평한~뾰족한] 면이에요.","ex":"원기둥 옆면, 원뿔 옆면","x":"원기둥은 면이 모두 곡면이에요.","why":"원기둥 위아래 밑면은 평평한 평면이에요.","fig":"cyl","ln":["평면"]},{"w":"모서리","en":"edge","d":"입체도형에서 [면과 면이 만나는 선분~점과 점이 만나는 곳~면 한가운데]이에요.","ex":"정육면체의 모서리 12개","x":"정육면체의 모서리는 8개예요.","why":"8개는 꼭짓점이에요. 모서리는 12개예요.","fig":"cube","ln":["점","선"]},{"w":"밑면","en":"base","d":"입체도형에서 [밑에 놓이는 기준 면~옆에 있는 면~가장 큰 면]이에요. 기둥은 2개, 뿔은 1개예요.","ex":"원기둥의 위아래 두 원","x":"기둥의 밑면은 1개예요.","why":"기둥은 위아래로 마주 보는 밑면이 2개예요.","fig":"prism","ln":["입체도형","옆면"]},{"w":"옆면","en":"lateral face","d":"입체도형에서 [밑면이 아닌~밑면인~가장 위의] 면이에요.","ex":"각기둥 옆면은 직사각형, 각뿔 옆면은 삼각형","x":"각뿔의 옆면은 직사각형이에요.","why":"각뿔의 옆면은 삼각형이에요.","fig":"prism","ln":["밑면"]},{"w":"겨냥도","en":"sketch","d":"입체도형의 모양을 알 수 있게 [보이는 선은 실선, 안 보이는 선은 점선으로~모든 선을 실선으로~앞면만] 그린 그림이에요.","ex":"뒤쪽 모서리 3개를 점선으로 그린 직육면체 그림","x":"겨냥도에서는 안 보이는 선을 그리지 않아요.","why":"안 보이는 선은 점선으로 그려요.","fig":"cube","ln":["전개도"]},{"w":"전개도","en":"net","d":"입체도형을 [펼쳐 평면에 그린~위에서 내려다본~잘라 낸 단면] 그림이에요.","ex":"정육면체 전개도는 정사각형 6개","x":"정육면체 전개도는 한 가지뿐이에요.","why":"정육면체 전개도는 11가지나 돼요.","fig":"net","ln":["겨냥도"]},{"w":"단면","en":"cross section","d":"입체도형을 [자른 면~겉 면~밑면]이에요.","ex":"김밥을 자른 단면은 원","x":"구를 어떻게 잘라도 단면은 사각형이에요.","why":"구는 어떻게 잘라도 단면이 원이에요.","ln":["평면","입체도형"]},{"w":"수직인 면","en":"perpendicular plane","d":"한 면에 대하여 [직각을 이루는~평행한~비스듬한] 면이에요.","ex":"정육면체에서 밑면에 수직인 면 4개","x":"정육면체에서 한 면에 수직인 면은 1개예요.","why":"한 면에 붙은 옆 네 면이 모두 수직이에요.","fig":"cube","ln":["수직"]},{"w":"교선","en":"line of intersection","d":"[면과 면이 만나서 생기는~점과 점이 만나는~선과 점이 만나는] 선이에요.","ex":"벽과 바닥이 만나는 선","x":"두 평면이 만나면 교선이 2개 생겨요.","why":"두 평면이 만나면 교선은 직선 하나예요.","ln":["교각","교점"]},{"w":"꼬인 위치","en":"skew position","d":"공간에서 두 직선이 [평행하지도 않고 만나지도 않는~평행한~수직으로 만나는] 위치예요.","ex":"직육면체에서 서로 다른 방향, 다른 높이의 두 모서리","x":"만나지 않는 두 직선은 언제나 평행해요.","why":"공간에서는 만나지 않으면서 평행하지도 않은 꼬인 위치가 있어요.","fig":"cube","ln":["평행"]},{"w":"무게중심","en":"center of gravity","d":"물체를 [한 점으로 받쳤을 때 기울지 않는~가장 무거운~가장 먼] 점이에요.","ex":"삼각형의 무게중심, 원의 무게중심 = 원의 중심","x":"무게중심은 늘 도형의 꼭짓점이에요.","why":"삼각형의 무게중심은 안쪽에 있어요.","ln":["중점"]}]},{"n":"기둥","id":"shape-prism","t":[{"w":"기둥","en":"prism and cylinder","d":"두 밑면이 [서로 평행하고 합동인~서로 다른 크기인~하나뿐인] 입체도형이에요.","ex":"각기둥, 원기둥","x":"기둥의 두 밑면은 크기가 달라도 돼요.","why":"두 밑면은 합동이에요. 크기가 다르면 기둥이 아니에요.","fig":"prism","ln":["각기둥","원기둥"]},{"w":"각기둥","en":"prism","d":"두 밑면이 합동인 [다각형이고 옆면이 직사각형인~원이고 옆면이 곡면인~다각형이고 옆면이 삼각형인] 기둥이에요.","ex":"삼각기둥, 사각기둥","x":"각기둥의 옆면은 삼각형이에요.","why":"각기둥의 옆면은 직사각형이에요.","fig":"prism","ln":["원기둥","각뿔"]},{"w":"삼각기둥","en":"triangular prism","d":"밑면이 [삼각형인~사각형인~원인] 각기둥이에요.","ex":"프리즘, 텐트 모양","x":"삼각기둥의 면은 3개예요.","why":"밑면 2 + 옆면 3 = 면 5개예요.","fig":"prism","ln":["각기둥","사각기둥"]},{"w":"사각기둥","en":"rectangular prism","d":"밑면이 [사각형인~삼각형인~오각형인] 각기둥이에요.","ex":"상자","x":"사각기둥의 면은 4개예요.","why":"밑면 2 + 옆면 4 = 면 6개예요.","fig":"cuboid","ln":["각기둥"]},{"w":"오각기둥","en":"pentagonal prism","d":"밑면이 [오각형인~육각형인~사각형인] 각기둥이에요. 면 7개, 꼭짓점 10개, 모서리 15개예요.","ex":"단면이 오각형인 연필","x":"오각기둥의 꼭짓점은 5개예요.","why":"위아래 밑면에 5개씩, 꼭짓점은 10개예요.","fig":"prism5","ln":["각기둥"]},{"w":"직육면체","en":"cuboid","d":"[직사각형 6개로 둘러싸인~정사각형 4개로 된~삼각형 6개로 된] 입체도형이에요.","ex":"벽돌, 우유 상자","x":"직육면체는 사각기둥이 아니에요.","why":"직육면체는 밑면이 직사각형인 사각기둥이에요.","fig":"cuboid","ln":["정육면체","사각기둥"]},{"w":"정육면체","en":"cube","d":"[정사각형 6개로 둘러싸인~직사각형 6개로 된~정삼각형 4개로 된] 입체도형이에요.","ex":"주사위","x":"정육면체는 직육면체가 아니에요.","why":"정사각형도 직사각형이라 정육면체도 직육면체예요.","fig":"cube","ln":["정다면체"]},{"w":"원기둥","en":"cylinder","d":"두 밑면이 [합동인 원이고 옆면이 곡면인~다각형이고 옆면이 직사각형인~원이 하나인] 기둥이에요.","ex":"깡통, 풀","x":"원기둥의 옆면을 펼치면 원이 돼요.","why":"옆면을 펼치면 직사각형이에요.","fig":"cyl","ln":["평면"]}]},{"n":"뿔","id":"shape-pyr","t":[{"w":"뿔","en":"pyramid and cone","d":"밑면이 하나이고 [옆면이 한 꼭짓점으로 모이는~옆면이 직사각형인~위아래가 같은] 입체도형이에요.","ex":"각뿔, 원뿔","x":"뿔의 밑면은 2개예요.","why":"뿔의 밑면은 1개예요.","fig":"pyr","ln":["각뿔","원뿔"]},{"w":"각뿔","en":"pyramid","d":"밑면이 [다각형이고 옆면이 삼각형인~원이고 옆면이 곡면인~다각형이고 옆면이 직사각형인] 뿔이에요.","ex":"삼각뿔, 사각뿔","x":"각뿔의 옆면은 직사각형이에요.","why":"각뿔의 옆면은 모두 삼각형이에요.","fig":"pyr","ln":["각기둥","원뿔"]},{"w":"사각뿔","en":"square pyramid","d":"밑면이 [사각형인~삼각형인~원인] 각뿔이에요.","ex":"이집트 피라미드","x":"사각뿔의 면은 4개예요.","why":"밑면 1 + 옆면 4 = 면 5개예요.","fig":"pyr","ln":["각뿔","다면체"]},{"w":"각뿔의 높이","en":"height of a pyramid","d":"각뿔의 꼭짓점에서 [밑면에 수직으로 내린~옆 모서리를 따라 잰~밑면 둘레를 잰] 선분의 길이예요.","ex":"피라미드 꼭대기에서 바닥까지 똑바로","x":"각뿔의 높이는 옆 모서리의 길이예요.","why":"옆 모서리는 비스듬해서 높이보다 길어요.","fig":"pyrh","ln":["각기둥","원뿔"]},{"w":"각뿔대","en":"frustum of a pyramid","d":"각뿔을 [밑면에 평행하게 잘라 낸 아래쪽~세로로 잘라 낸 반쪽~꼭대기 작은 뿔] 부분이에요.","ex":"윗면이 작은 사각 받침대","x":"각뿔대의 두 밑면은 합동이에요.","why":"각뿔대의 두 밑면은 모양은 같고 크기가 달라요.","ln":["각뿔","각기둥"]},{"w":"원뿔","en":"cone","d":"밑면이 [원이고 옆면이 곡면인~다각형이고 옆면이 삼각형인~원이 2개인] 뿔이에요.","ex":"고깔모자, 아이스크림 콘","x":"원뿔에는 꼭짓점이 없어요.","why":"원뿔에는 뾰족한 꼭짓점이 1개 있어요.","fig":"cone","ln":["원뿔대","각뿔"]},{"w":"원뿔의 높이","en":"height of a cone","d":"원뿔의 꼭짓점에서 [밑면에 수직으로 내린~모선을 따라 잰~밑면 지름을 잰] 선분의 길이예요.","ex":"고깔 꼭대기에서 바닥 가운데까지","x":"원뿔의 높이와 모선의 길이는 같아요.","why":"모선은 비스듬해서 높이보다 길어요.","fig":"cone","ln":["원뿔"]},{"w":"모선","en":"generator","d":"원뿔의 꼭짓점과 [밑면 둘레의 한 점을 이은~밑면의 중심을 이은~다른 원뿔을 이은] 선분이에요.","ex":"원뿔 옆면의 비스듬한 선","x":"원뿔의 모선은 1개뿐이에요.","why":"밑면 둘레의 점마다 이을 수 있어서 모선은 셀 수 없이 많아요.","fig":"cone","ln":["원뿔"]},{"w":"원뿔대","en":"frustum of a cone","d":"원뿔을 [밑면에 평행하게 잘라 낸 아래쪽~세로로 자른 반쪽~꼭대기 작은 원뿔] 부분이에요.","ex":"양동이, 화분 모양","x":"원뿔대의 두 밑면은 크기가 같아요.","why":"두 밑면은 크기가 다른 원이에요.","ln":["원뿔"]}]},{"n":"여러 가지 입체도형","id":"shape-poly3","t":[{"w":"다면체","en":"polyhedron","d":"[다각형으로만 둘러싸인~곡면이 있는~원으로 된] 입체도형이에요.","ex":"사면체, 육면체(상자)","x":"원기둥은 다면체예요.","why":"원기둥은 곡면이 있어서 다면체가 아니에요.","ln":["정다면체"]},{"w":"정다면체","en":"regular polyhedron","d":"모든 면이 [합동인 정다각형이고 꼭짓점마다 모인 면의 수가 같은~직사각형인~크기가 다른] 다면체예요. 5가지뿐이에요.","ex":"정사면체, 정육면체, 정팔면체, 정십이면체, 정이십면체","x":"정다면체는 끝없이 많은 종류가 있어요.","why":"딱 5가지뿐이에요.","ln":["정다각형"]},{"w":"정사면체","en":"regular tetrahedron","d":"[합동인 정삼각형 4개로~정사각형 4개로~정삼각형 6개로] 이루어진 입체도형이에요.","ex":"삼각뿔 모양 주사위","x":"정사면체의 꼭짓점은 3개예요.","why":"꼭짓점은 4개예요.","ln":["정다면체"]},{"w":"구(공)","en":"sphere","d":"[반원을 지름을 축으로 한 바퀴 돌려 만든~직사각형을 돌린~원을 접은] 입체도형이에요.","ex":"공, 구슬","x":"구를 자르면 단면이 사각형일 때도 있어요.","why":"구는 어떻게 잘라도 단면이 원이에요.","fig":"sphere","ln":["원","회전체"]},{"w":"회전체","en":"solid of revolution","d":"평면도형을 [한 직선을 축으로 한 바퀴 돌려 만든~옆으로 밀어서 만든~접어서 만든] 입체도형이에요.","ex":"원기둥, 원뿔, 구","x":"사각뿔은 회전체예요.","why":"사각뿔은 돌려서 만들 수 없어서 회전체가 아니에요.","fig":"cyl","ln":["축"]}]}]},{"n":"측정","id":"meas","br":[{"n":"비교하는 말","id":"meas-cmpword","t":[{"w":"길다","en":"long","d":"두 물체를 비교할 때 한쪽 끝을 맞추고 [다른 쪽 끝이 더 나가는~더 무거운~더 넓은] 것이에요.","ex":"연필이 지우개보다 길어요.","x":"끝을 맞추지 않고 보아도 길이를 바로 비교할 수 있어요.","why":"한쪽 끝을 맞춰야 정확히 비교할 수 있어요.","fig":"bars","ln":["짧다","길이"]},{"w":"짧다","en":"short","d":"두 물체를 비교할 때 [길이가 덜 나가는~무게가 덜 나가는~양이 적은] 것이에요. 반대말은 '길다'예요.","ex":"지우개가 연필보다 짧아요.","x":"'짧다'는 무게를 비교하는 말이에요.","why":"'짧다'는 길이를 비교하는 말이에요.","fig":"bars","ln":["길다"]},{"w":"가깝다","en":"near","d":"기준에서 [거리가 짧은~거리가 먼~무게가 가벼운] 것이에요. 반대말은 '멀다'예요.","ex":"우리 집에서 우체국이 학교보다 가까워요.","x":"가깝다는 물건 크기를 비교하는 말이에요.","why":"가깝다는 거리를 비교하는 말이에요.","ln":["멀다"]},{"w":"멀다","en":"far","d":"기준에서 [거리가 많이 떨어진~거리가 짧은~크기가 큰] 것이에요. 반대말은 '가깝다'예요.","ex":"우리 집에서 학교가 우체국보다 멀어요.","x":"멀다와 가깝다는 같은 뜻이에요.","why":"서로 반대말이에요.","ln":["가깝다"]},{"w":"넓다","en":"wide","d":"면이나 바닥의 [넓이가 큰~길이가 긴~무게가 무거운] 것이에요.","ex":"운동장이 교실보다 넓어요.","x":"길쭉하면 무조건 넓어요.","why":"넓은지는 넓이(차지하는 평면의 크기)로 비교해요.","ln":["넓이"]},{"w":"무겁다","en":"heavy","d":"어떤 기준보다 [무게가 많이 나가는~길이가 긴~양이 많은] 것이에요. 반대말은 '가볍다'예요.","ex":"수박이 사과보다 무거워요.","x":"크기가 큰 물건은 언제나 더 무거워요.","why":"큰 풍선이 작은 쇠공보다 가벼운 것처럼 크기와 무게는 달라요.","fig":"scale","ln":["가볍다"]},{"w":"가볍다","en":"light","d":"어떤 기준보다 [무게가 덜 나가는~길이가 짧은~넓이가 좁은] 것이에요.","ex":"깃털은 돌보다 가벼워요.","x":"가볍다는 기준 없이도 말할 수 있어요.","why":"무엇과 비교해 가벼운지 기준이 있어야 해요.","fig":"scale","ln":["무겁다"]},{"w":"가로","en":"width","d":"[왼쪽에서 오른쪽으로~위에서 아래로~앞에서 뒤로] 놓인 방향이나 길이예요.","ex":"책상을 왼쪽 끝에서 오른쪽 끝까지 잰 길이","x":"가로는 늘 세로보다 길어요.","why":"가로와 세로 중 어느 쪽이 길지는 물건마다 달라요.","fig":"rect","ln":["세로"]},{"w":"세로","en":"length (vertical)","d":"[위에서 아래로~왼쪽에서 오른쪽으로~비스듬히] 놓인 방향이나 길이예요.","ex":"문을 위 끝에서 아래 끝까지 잰 길이","x":"물건을 눕혀도 세로는 그대로예요.","why":"놓는 방향이 바뀌면 가로와 세로도 바뀔 수 있어요.","fig":"rect","ln":["가로"]},{"w":"너비","en":"width","d":"평면이나 물체를 가로로 건너지르는 [길이~무게~높이]예요. '폭'이라고도 해요.","ex":"강의 이쪽 기슭에서 건너편 기슭까지 잰 길이","x":"너비는 위아래 길이예요.","why":"너비는 가로로 건너지르는 길이예요.","ln":["폭"]},{"w":"폭","en":"breadth","d":"양쪽 끝 사이의 [거리~무게~양]예요. 보통 길이보다 짧은 쪽이에요.","ex":"길의 폭, 천의 폭","x":"폭과 너비는 서로 다른 뜻이에요.","why":"폭과 너비는 같은 뜻으로 써요.","ln":["측정","너비","길이"]},{"w":"두께","en":"thickness","d":"두꺼운 정도, 즉 [한 면과 마주 보는 면 사이~양 끝 사이 가로~바닥에서 꼭대기] 거리예요.","ex":"책을 덮었을 때 앞표지에서 뒤표지까지 3cm","x":"두께는 길이 단위로 잴 수 없어요.","why":"두께도 mm, cm 같은 길이 단위로 재요.","ln":["폭"]},{"w":"깊이","en":"depth","d":"기준이 되는 면에서 [밑바닥까지~위쪽 끝까지~옆까지] 거리예요.","ex":"수영장 깊이 1.2m","x":"깊이는 위로 잰 거리예요.","why":"깊이는 아래쪽 바닥까지 잰 거리예요.","ln":["길이"]},{"w":"거리","en":"distance","d":"두 점이나 장소가 [떨어져 있는 정도~얼마나 무거운지~얼마나 넓은지]예요. 두 점 사이 가장 짧은 길이예요.","ex":"집에서 학교까지 거리","x":"두 점 사이 거리는 구불구불한 길로 잰 길이예요.","why":"두 점 사이 거리는 곧게 이은 선분의 길이예요.","fig":"lineseg","ln":["길이"]},{"w":"수평","en":"horizontal","d":"잔잔한 물의 표면처럼 [기울지 않고 평평한~비스듬한~세워진] 상태예요.","ex":"물을 담은 컵의 수면, 양쪽 무게가 같은 저울","x":"기울어진 컵 속 물의 표면은 기울어져요.","why":"컵을 기울여도 물의 표면은 수평을 이뤄요.","ln":["평행"]}]},{"n":"재기와 단위","id":"meas-unit","t":[{"w":"측정","en":"measurement","d":"어떤 양을 [기준이 되는 양과 비교해 재는~눈으로 대충 보는~더하는] 것이에요.","ex":"자로 길이 재기, 저울로 무게 재기","x":"측정은 기준이 없어도 돼요.","why":"1cm, 1kg 같은 기준(단위)이 있어야 측정할 수 있어요.","ln":["임의 단위","표준 단위"]},{"w":"단위","en":"unit","d":"길이, 무게, 넓이를 수로 나타낼 때 [기준이 되는 양~가장 큰 양~아무 양]이에요.","ex":"m, kg, L","x":"단위를 빼고 수만 써도 뜻이 통해요.","why":"'3'만 쓰면 3m인지 3kg인지 몰라요. 단위를 꼭 써야 해요.","ln":["임의 단위","표준 단위"]},{"w":"임의 단위","en":"arbitrary unit","d":"[사람마다 정한~모두가 약속한~나라가 정한] 기준으로 재는 단위예요.","ex":"뼘, 걸음, 클립 개수","x":"임의 단위로 재면 누가 재도 같은 값이 나와요.","why":"사람마다 뼘 길이가 달라서 값이 달라져요.","ln":["표준 단위","단위"]},{"w":"뼘","en":"span","d":"엄지와 새끼손가락을 [쫙 벌린 길이~오므린 길이~손바닥 넓이]로 재는 임의 단위예요.","ex":"책상 가로가 5뼘","x":"아빠의 한 뼘과 내 한 뼘은 길이가 같아요.","why":"손 크기가 달라서 사람마다 한 뼘 길이가 달라요.","ln":["임의 단위"]},{"w":"표준 단위","en":"standard unit","d":"[모두가 같은 크기로 쓰기로 약속한~사람마다 정한~옛날에만 쓰던] 단위예요.","ex":"1cm, 1kg, 1L","x":"뼘은 표준 단위예요.","why":"뼘은 사람마다 달라서 임의 단위예요.","ln":["단위","임의 단위"]},{"w":"미터법","en":"metric system","d":"길이는 미터, 무게는 킬로그램처럼 [십진법으로 단위를 정한~사람마다 다른~옛 단위를 쓰는] 방법이에요.","ex":"1km = 1000m, 1m = 100cm","x":"미터법에서는 단위가 12배씩 커져요.","why":"미터법은 10, 100, 1000배씩 커져요.","ln":["미터","단위"]},{"w":"자","en":"ruler","d":"[길이를 재거나 곧은 선을 긋는~무게를 다는~각도를 재는] 도구예요.","ex":"곧은자, 줄자, 삼각자","x":"자는 0이 아닌 곳에 맞춰도 그 끝 눈금을 그대로 읽으면 돼요.","why":"0이 아닌 곳에서 재면 끝 눈금에서 시작 눈금을 빼야 해요.","fig":"ruler","ln":["직선"]},{"w":"삼각자","en":"set square","d":"[삼각형 모양의~원 모양의~사각형 모양의] 자예요. 직각과 평행선 긋기에 써요.","ex":"30°·60°·90° 삼각자, 45°·45°·90° 삼각자","x":"삼각자에는 직각이 없어요.","why":"두 삼각자 모두 직각이 하나씩 있어요.","fig":"trir","ln":["자"]},{"w":"눈금","en":"scale mark","d":"자나 저울에 [수나 양을 읽을 수 있게 새긴~장식으로 그린~숫자만 쓴] 금이에요.","ex":"자의 1mm 눈금","x":"눈금 한 칸은 언제나 1이에요.","why":"눈금 한 칸이 2나 5, 10을 나타낼 때도 있어요. 먼저 한 칸 값을 확인해요.","fig":"ruler","ln":["자","저울"]},{"w":"모눈종이","en":"graph paper","d":"[가로세로 줄이 같은 간격으로 그어진~줄이 없는~원이 그려진] 종이예요.","ex":"모눈 한 칸이 1cm × 1cm","x":"모눈종이는 칸마다 크기가 달라요.","why":"모든 칸이 같은 크기의 정사각형이에요.","fig":"grid","ln":["그래프"]},{"w":"점판","en":"geoboard","d":"[같은 간격으로 못이나 점을 박은~줄이 없는~원 모양의] 판이에요. 고무줄로 도형을 만들어요.","ex":"고무줄로 삼각형 만들기","x":"점판의 점 간격은 제각각이에요.","why":"점들은 같은 간격으로 놓여 있어요.","fig":"geo","ln":["모눈종이"]}]},{"n":"길이","id":"meas-len","t":[{"w":"길이","en":"length","d":"한 점에서 다른 점까지의 [거리~무게~넓이]예요.","ex":"연필의 길이 15cm","x":"길이는 단위 없이 숫자만 써도 돼요.","why":"15만 쓰면 cm인지 m인지 몰라요.","fig":"ruler","ln":["단위길이"]},{"w":"단위길이","en":"unit length","d":"길이를 잴 때 [기준이 되는 길이~가장 긴 길이~한 뼘만]예요.","ex":"1cm, 1m","x":"단위길이는 언제나 1m예요.","why":"1mm, 1cm, 1km도 단위길이가 될 수 있어요.","fig":"ruler","ln":["길이"]},{"w":"밀리미터","en":"millimeter","d":"1cm를 똑같이 [10칸~100칸~1000칸]으로 나눈 한 칸의 길이예요. 1mm라고 써요.","ex":"자의 가장 작은 눈금 1mm","x":"1cm = 100mm예요.","why":"1cm = 10mm예요. 1m = 1000mm예요.","fig":"ruler","ln":["미터","미터법"]},{"w":"센티미터","en":"centimeter","d":"1m를 똑같이 [100칸~10칸~1000칸]으로 나눈 한 칸의 길이예요. 1cm라고 써요.","ex":"손톱 너비가 약 1cm","x":"1m = 10cm예요.","why":"1m = 100cm예요.","fig":"ruler","ln":["미터"]},{"w":"미터","en":"meter","d":"길이의 [기본 단위~무게 단위~들이 단위]예요. 1m = 100cm예요.","ex":"어른 큰 걸음 한 번이 약 1m","x":"1m는 1000cm예요.","why":"1m는 100cm예요. 1000m가 1km예요.","ln":["길이"]},{"w":"킬로미터","en":"kilometer","d":"1m의 [1000배~100배~10배]인 길이예요. 1km라고 써요.","ex":"걸어서 15분 정도 거리","x":"1km = 100m예요.","why":"1km = 1000m예요. 킬로(k)는 1000을 뜻해요.","ln":["미터","센티미터","단위"]},{"w":"둘레","en":"perimeter","d":"도형의 [가장자리를 한 바퀴 돈 길이~안쪽 넓이~대각선 길이]예요.","ex":"한 변이 10cm인 정사각형의 둘레 40cm","x":"넓이가 같으면 둘레도 늘 같아요.","why":"넓이가 같아도 모양에 따라 둘레는 달라요(4×4와 2×8).","fig":"sq","ln":["길이"]}]},{"n":"넓이","id":"meas-area","t":[{"w":"넓이","en":"area","d":"평면이 [차지하는 크기~둘레의 길이~무게]예요. cm², m²로 나타내요.","ex":"1cm²짜리 칸 6개 = 6cm²","x":"넓이는 cm로 나타내요.","why":"넓이 단위는 cm², m²처럼 '제곱'이 붙어요.","fig":"grid","ln":["제곱센티미터"]},{"w":"단위넓이","en":"unit area","d":"넓이를 잴 때 [기준이 되는 넓이~가장 큰 넓이~둘레]예요.","ex":"1cm², 1m²","x":"단위넓이는 언제나 손바닥 크기예요.","why":"표준 단위넓이는 1cm², 1m² 등이에요.","fig":"grid","ln":["넓이"]},{"w":"제곱센티미터","en":"square centimeter","d":"한 변이 [1cm인 정사각형의~1m인 정사각형의~1cm인 선분의] 넓이예요. 1cm²라고 써요.","ex":"모눈 한 칸","x":"1cm²는 1cm 선분의 길이예요.","why":"1cm²는 넓이라서 정사각형 한 칸의 크기예요.","fig":"grid","ln":[]},{"w":"제곱미터","en":"square meter","d":"한 변이 [1m인 정사각형의~1cm인 정사각형의~1km인 정사각형의] 넓이예요. 1m²라고 써요.","ex":"1m² = 10000cm²","x":"1m² = 100cm²예요.","why":"가로 100cm × 세로 100cm라서 10000cm²예요.","ln":["미터"]},{"w":"아르","en":"are","d":"한 변이 [10m인 정사각형의~1m인~100m인] 넓이예요. 1a = 100m²예요.","ex":"작은 텃밭 넓이","x":"1a = 10m²예요.","why":"10m × 10m = 100m²라서 1a = 100m²예요.","ln":["제곱미터","헥타르"]},{"w":"헥타르","en":"hectare","d":"한 변이 [100m인 정사각형의~10m인~1km인] 넓이예요. 1ha = 10000m²예요.","ex":"축구장 하나보다 조금 넓은 땅","x":"1ha = 100m²예요.","why":"100m × 100m = 10000m²예요.","ln":["제곱미터","아르"]},{"w":"밑넓이","en":"base area","d":"입체도형에서 [한 밑면의 넓이~모든 면의 넓이~옆면의 넓이]예요.","ex":"원기둥 밑넓이 = 밑면인 원 하나의 넓이","x":"기둥의 밑넓이는 두 밑면 넓이를 더한 값이에요.","why":"밑넓이는 밑면 하나의 넓이예요.","fig":"prism","ln":["밑면","넓이"]},{"w":"겉넓이","en":"surface area","d":"입체도형 [겉면 전체의 넓이~한 면의 넓이~부피]예요.","ex":"정육면체 겉넓이 = 한 면 넓이 × 6","x":"겉넓이는 부피와 같아요.","why":"겉넓이는 겉을 감싸는 넓이, 부피는 차지하는 공간이에요.","fig":"net","ln":["넓이"]},{"w":"원의 넓이","en":"area of a circle","d":"원이 차지하는 평면의 크기예요. [반지름 × 반지름 × 원주율~지름 × 원주율~반지름 × 2]로 구해요.","ex":"반지름 10cm → 10 × 10 × 3.14 = 314cm²","x":"원의 넓이 = 지름 × 3.14예요.","why":"지름 × 3.14는 원주(둘레)예요. 넓이는 반지름 × 반지름 × 3.14예요.","fig":"circ","ln":["원","원의 중심","원의 지름","원주율"]},{"w":"원기둥의 겉넓이","en":"surface area of a cylinder","d":"[두 밑면 넓이 + 옆면 넓이~밑면 하나 넓이~옆면 넓이만]예요. 옆면은 펼치면 직사각형이에요.","ex":"(밑면 넓이) × 2 + (밑면 둘레) × (높이)","x":"원기둥 옆면의 가로는 밑면의 지름이에요.","why":"옆면을 펼친 직사각형의 가로는 밑면의 둘레(원주)예요.","fig":"cyl","ln":["원기둥"]}]},{"n":"부피와 들이","id":"meas-vol","t":[{"w":"부피","en":"volume","d":"물체가 [공간에서 차지하는 크기~평면에서 차지하는 크기~무게]예요. cm³, m³로 나타내요.","ex":"1cm³짜리 쌓기나무 8개 = 8cm³","x":"무거운 물체가 언제나 부피도 커요.","why":"솜 한 봉지는 가볍지만 부피가 클 수 있어요.","fig":"cube","ln":["들이","단위부피"]},{"w":"단위부피","en":"unit volume","d":"부피를 잴 때 [기준이 되는 부피~가장 큰 부피~넓이]예요.","ex":"1cm³, 1m³","x":"단위부피는 정사각형 한 칸이에요.","why":"단위부피는 정육면체 하나의 크기예요.","fig":"cube","ln":["부피"]},{"w":"세제곱센티미터","en":"cubic centimeter","d":"한 모서리가 [1cm인 정육면체의~1cm인 정사각형의~1m인 정육면체의] 부피예요. 1cm³라고 써요.","ex":"각설탕 하나 정도","x":"1cm³는 정사각형 한 칸의 넓이예요.","why":"1cm³는 넓이가 아니라 부피예요.","fig":"cube","ln":["세제곱미터","부피"]},{"w":"세제곱미터","en":"cubic meter","d":"한 모서리가 [1m인 정육면체의~1cm인 정육면체의~1m인 정사각형의] 부피예요. 1m³ = 1000000cm³예요.","ex":"1m³ 물의 무게는 약 1t","x":"1m³ = 100cm³예요.","why":"100 × 100 × 100 = 1000000cm³예요.","fig":"cube","ln":["세제곱센티미터","부피"]},{"w":"원기둥의 부피","en":"volume of a cylinder","d":"[밑넓이 × 높이~밑면 둘레 × 높이~반지름 × 높이]로 구해요.","ex":"밑넓이 10cm², 높이 5cm → 50cm³","x":"원기둥의 부피 = 지름 × 높이예요.","why":"원기둥의 부피 = 밑넓이(원의 넓이) × 높이예요.","fig":"cyl","ln":["원기둥"]},{"w":"들이","en":"capacity","d":"그릇 [안쪽에 담을 수 있는 양~겉의 넓이~무게]이에요. L, mL로 나타내요.","ex":"물병의 들이 500mL","x":"속이 꽉 찬 쇠공에도 들이가 있어요.","why":"속이 비어 무엇을 담을 수 있어야 들이가 있어요.","fig":"cup","ln":["리터","부피"]},{"w":"리터","en":"liter","d":"들이의 단위예요. 한 모서리가 [10cm인 정육면체에~1cm인 정육면체에~1m인 정육면체에] 가득 담기는 양이에요. 1L라고 써요.","ex":"우유 큰 팩 1L","x":"1L = 100mL예요.","why":"1L = 1000mL예요.","fig":"cup","ln":["밀리리터","들이","부피"]},{"w":"밀리리터","en":"milliliter","d":"1L를 똑같이 [1000으로~100으로~10으로] 나눈 양이에요. 1mL라고 써요.","ex":"1mL = 1cm³ (한 모서리 1cm인 정육면체만큼)","x":"1mL = 1L예요.","why":"1000mL가 모여야 1L예요.","fig":"cup","ln":["리터","들이"]},{"w":"안치수","en":"inside measure","d":"그릇 [안쪽 모서리의~바깥쪽 모서리의~뚜껑의] 길이예요. 들이를 구할 때 써요.","ex":"상자 안쪽 가로·세로·높이","x":"들이는 바깥 치수로 구해요.","why":"그릇 벽 두께만큼 빼야 하니 안치수로 구해요.","ln":["모서리","부피","들이"]}]},{"n":"무게와 온도","id":"meas-weight","t":[{"w":"무게","en":"weight","d":"물체의 [무거운 정도~길이~부피]예요. g, kg, t으로 나타내요.","ex":"사과 한 개 약 300g","x":"크기가 같으면 무게도 꼭 같아요.","why":"크기가 같아도 재료에 따라 무게가 달라요(나무공과 쇠공).","fig":"scale","ln":["단위","킬로그램"]},{"w":"그램","en":"gram","d":"무게의 [단위~길이 단위~들이 단위]예요. 1g이라고 써요.","ex":"클립 한 개 약 1g","x":"1g은 1kg보다 무거워요.","why":"1kg = 1000g이라 1g이 훨씬 가벼워요.","fig":"scale","ln":["킬로그램","무게"]},{"w":"킬로그램","en":"kilogram","d":"1g의 [1000배~100배~10배]인 무게예요. 1kg이라고 써요.","ex":"물 1L의 무게 약 1kg","x":"1kg = 100g이에요.","why":"1kg = 1000g이에요.","fig":"scale","ln":["그램","톤","단위"]},{"w":"톤","en":"ton","d":"1kg의 [1000배~100배~10배]인 무게예요. 1t이라고 써요.","ex":"작은 자동차 약 1t","x":"1t = 100kg이에요.","why":"1t = 1000kg이에요.","ln":["킬로그램","무게"]},{"w":"저울","en":"scales","d":"[무게를 재는~길이를 재는~시간을 재는] 기구예요.","ex":"체중계, 윗접시저울","x":"저울은 0을 맞추지 않아도 돼요.","why":"바늘이나 숫자가 0에서 시작해야 바르게 잴 수 있어요.","fig":"scale","ln":["측정"]},{"w":"기온","en":"air temperature","d":"[공기의 온도~물의 깊이~바람의 세기]예요. 섭씨(°C)로 나타내요.","ex":"오늘 기온 −3°C","x":"0°C보다 낮은 온도는 없어요.","why":"−5°C처럼 0°C보다 낮은 기온도 있어요.","fig":"therm","ln":["측정"]}]},{"n":"시각과 시간","id":"meas-time","t":[{"w":"시각","en":"point in time","d":"[어느 한 때~두 때 사이의 길이~하루 전체]를 나타내는 말이에요.","ex":"지금 시각 3시 30분","x":"시각과 시간은 같은 말이에요.","why":"시각은 '때', 시간은 두 시각 사이의 '길이'예요.","fig":"clock","ln":["오전","오후","시간"]},{"w":"시간","en":"duration","d":"[한 시각에서 다른 시각까지의 길이~어느 한 때~시계 바늘]예요.","ex":"오후 5시부터 7시까지 2시간","x":"3시 30분은 시간이에요.","why":"3시 30분은 시각이에요. '30분 동안'이 시간이에요.","fig":"clock","ln":["시각"]},{"w":"시계","en":"clock","d":"[시각과 시간을 알 수 있는~길이를 재는~무게를 다는] 장치예요.","ex":"벽시계, 모래시계, 해시계","x":"짧은바늘은 분을 가리켜요.","why":"짧은바늘은 시, 긴바늘은 분을 가리켜요.","fig":"clock","ln":["시각","시간"]},{"w":"오전","en":"a.m.","d":"하루 중 밤 12시부터 [낮 12시까지~밤 12시까지~저녁 6시까지]예요.","ex":"오전 8시 = 아침 8시","x":"오전 2시는 낮이에요.","why":"오전 2시는 한밤중(새벽)이에요.","ln":["오후"]},{"w":"오후","en":"p.m.","d":"하루 중 낮 12시부터 [밤 12시까지~낮 12시까지~아침까지]예요.","ex":"오후 3시 = 15시","x":"오후 3시는 밤 3시예요.","why":"오후 3시는 낮 12시에서 3시간 지난 낮이에요. 24시간제로 15시예요.","ln":["오전"]},{"w":"낮의 길이","en":"length of daytime","d":"해가 [뜰 때부터 질 때까지~질 때부터 뜰 때까지~가장 높이 뜬 때]의 시간이에요.","ex":"여름에 길고 겨울에 짧아요.","x":"낮의 길이는 1년 내내 같아요.","why":"여름에는 길고 겨울에는 짧아요.","ln":["밤의 길이"]},{"w":"밤의 길이","en":"length of nighttime","d":"해가 [진 때부터 다시 뜰 때까지~뜰 때부터 질 때까지~자정부터 정오까지]의 시간이에요.","ex":"밤의 길이 = 24시간 − 낮의 길이","x":"낮이 길어지면 밤도 길어져요.","why":"하루가 24시간이라 낮이 길어지면 밤은 짧아져요.","ln":["낮의 길이"]},{"w":"년","en":"year","d":"해를 세는 단위로, 지구가 [태양 둘레를 한 바퀴 도는~스스로 한 바퀴 도는~달이 한 바퀴 도는] 데 걸리는 시간이에요.","ex":"1년 = 12달 = 약 365일","x":"1년은 늘 365일이에요.","why":"윤년(대개 4년에 한 번)은 2월이 29일이라 366일이에요.","ln":["시간"]},{"w":"달력","en":"calendar","d":"날짜를 [연, 월, 일, 요일로 나누어 보여 주는~시각만 보여 주는~무게를 적은] 것이에요.","ex":"1주일 = 7일","x":"어느 달이나 31일이에요.","why":"30일까지인 달과 2월처럼 28·29일인 달도 있어요.","ln":["년"]},{"w":"나이","en":"age","d":"태어나서 [살아온 해의 수~키~몸무게]예요.","ex":"10살","x":"나이는 해가 바뀌어도 그대로예요.","why":"해(또는 생일)가 지나면 한 살 늘어요.","ln":["년"]}]}]},{"n":"규칙과 관계","id":"rel","br":[{"n":"규칙","id":"rel-pattern","t":[{"w":"규칙","en":"rule","d":"수나 모양이 [일정한 약속에 따라~아무렇게나~딱 한 번만] 놓여 있는 것이에요.","ex":"1, 3, 5, 7 … → 2씩 커지는 규칙","x":"앞의 세 개만 맞으면 규칙을 찾은 거예요.","why":"몇 개만 보고 정하면 틀릴 수 있어요. 더 많은 수로 확인해야 해요.","ln":["수열"]},{"w":"수열","en":"sequence","d":"[일정한 규칙에 따라 늘어놓은~크기 상관없이 섞은~딱 두 개인] 수의 열이에요.","ex":"1, 1, 2, 3, 5, 8 … (앞의 두 수를 더해요)","x":"수열은 꼭 같은 수만큼 커져야 해요.","why":"1, 2, 4, 8처럼 두 배씩 커지는 수열도 있어요.","ln":["규칙"]},{"w":"마방진","en":"magic square","d":"정사각형 칸에 수를 넣어 [가로, 세로, 대각선의 합이 모두 같게~가로의 합만 같게~크기 순서대로] 만든 표예요.","ex":"3×3 마방진은 줄마다 합이 15","x":"마방진은 가로 줄만 합이 같으면 돼요.","why":"세로와 대각선의 합도 모두 같아야 해요.","fig":"magic","ln":[]}]},{"n":"대응과 함수","id":"rel-func","t":[{"w":"대응관계","en":"correspondence","d":"두 양이 [한쪽이 변하면 다른 쪽도 정해진 규칙으로 변하는~서로 아무 상관 없는~늘 같은] 관계예요.","ex":"아버지 나이 = 내 나이 + 27","x":"대응관계는 두 양이 늘 같아야 해요.","why":"같을 필요는 없고 규칙으로 짝지어지면 돼요.","fig":"corr","ln":["대응","관계식"]},{"w":"대응표","en":"correspondence table","d":"대응관계를 [표로 나타낸~그래프로 나타낸~말로만 쓴] 것이에요.","ex":"내 나이 3, 8, 13 / 아버지 나이 30, 35, 40","x":"대응표에는 규칙이 없어도 돼요.","why":"대응표를 보면 두 양 사이의 규칙을 찾을 수 있어요.","fig":"corr","ln":["대응관계"]},{"w":"관계식","en":"relational expression","d":"두 양 사이의 관계를 [식으로 나타낸~그림으로 그린~표로 쓴] 것이에요.","ex":"□ + 3 = △","x":"관계식에는 기호를 쓰면 안 돼요.","why":"□, △, x, y 같은 기호를 써서 관계를 나타내요.","ln":["등식"]},{"w":"함수","en":"function","d":"x의 값이 정해지면 [y의 값이 하나로 정해지는~y의 값이 여러 개인~y가 없는] 관계예요.","ex":"자판기: 버튼 A를 누르면 늘 음료 A","x":"버튼 하나를 눌렀는데 음료가 아무거나 나와도 함수예요.","why":"x 하나에 y가 딱 하나로 정해져야 함수예요.","ln":["대응관계"]},{"w":"순서쌍","en":"ordered pair","d":"두 수를 [순서를 정해 짝지은~순서 없이 묶은~더한] 것이에요.","ex":"(2, 1)","x":"(2, 1)과 (1, 2)는 같은 순서쌍이에요.","why":"순서가 달라서 서로 다른 순서쌍이에요.","fig":"coord","ln":["좌표평면","쌍"]},{"w":"좌표평면","en":"coordinate plane","d":"[가로축과 세로축이 그려진~눈금 없는~원이 그려진] 평면이에요. 점의 위치를 순서쌍으로 나타내요.","ex":"점 P(3, 2): 오른쪽 3, 위로 2","x":"좌표 (3, 2)는 위로 3, 오른쪽 2예요.","why":"앞의 수가 가로(x), 뒤의 수가 세로(y)예요.","fig":"coord","ln":["원점"]},{"w":"원점","en":"origin","d":"수직선이나 좌표평면에서 [기준이 되는 0인~가장 큰~맨 끝] 점이에요.","ex":"좌표평면의 원점 O(0, 0)","x":"원점의 좌표는 (1, 1)이에요.","why":"원점은 (0, 0)이에요.","fig":"coord","ln":["좌표평면","수직선"]}]},{"n":"비와 비율","id":"rel-ratio","t":[{"w":"비","en":"ratio","d":"두 양을 [기호 :를 써서 비교한~더한~뺀] 것이에요.","ex":"사과 3개, 배 4개 → 3 : 4","x":"3 : 4와 4 : 3은 같은 비예요.","why":"기준이 바뀌어서 서로 다른 비예요.","ln":["비율","비례"]},{"w":"전항","en":"antecedent","d":"비에서 [기호 : 앞에 있는~기호 : 뒤에 있는~가운데 있는] 수예요. 비교하는 양이에요.","ex":"3 : 2에서 전항은 3","x":"3 : 2에서 전항은 2예요.","why":"기호 앞의 3이 전항이에요.","ln":["후항"]},{"w":"후항","en":"consequent","d":"비에서 [기호 : 뒤에 있는~기호 : 앞에 있는~맨 앞의] 수예요. 기준이 되는 양이에요.","ex":"3 : 2에서 후항은 2","x":"후항은 비교하는 양이에요.","why":"후항은 기준량이에요. 비교하는 양은 전항이에요.","ln":["전항","비례식"]},{"w":"기준량","en":"base quantity","d":"비에서 [기준이 되는~비교하는~가장 큰] 양이에요. 후항이에요.","ex":"4에 대한 3의 비 → 기준량 4","x":"'4에 대한 3의 비'에서 기준량은 3이에요.","why":"'~에 대한'이 붙은 4가 기준이에요.","ln":["비율","비의 값"]},{"w":"비의 값","en":"value of a ratio","d":"[비교하는 양 ÷ 기준량~기준량 ÷ 비교하는 양~두 양의 합]으로 나타낸 값이에요.","ex":"4 : 9의 비의 값 = 4/9","x":"3 : 5의 비의 값은 5/3이에요.","why":"3 ÷ 5 = 3/5이에요.","ln":["비율","기준량"]},{"w":"비율","en":"rate","d":"기준량에 대한 [비교하는 양의 크기~기준량의 크기~두 양의 차]예요. 분수, 소수, 백분율로 나타내요.","ex":"과일 5개 중 배가 3개 → 배의 비율 3/5","x":"비율은 늘 1보다 커요.","why":"비교하는 양이 기준량보다 작으면 1보다 작아요(3/5).","ln":["비의 값"]},{"w":"백분율","en":"percentage","d":"기준량을 [100으로 할 때의~10으로 할 때의~1000으로 할 때의] 비율이에요. %를 써요.","ex":"0.85 = 85/100 = 85%","x":"0.5는 5%예요.","why":"0.5 = 50/100 = 50%예요.","ln":["비율","퍼센트"]},{"w":"퍼센트","en":"percent","d":"백분율의 단위예요. [100분의 얼마~10분의 얼마~1000분의 얼마]라는 뜻이에요. %라고 써요.","ex":"1% = 1/100, 25% = 25/100","x":"25%는 1/25이에요.","why":"25% = 25/100 = 1/4이에요.","ln":["백분율","비율"]},{"w":"할푼리","en":"hal-pun-ri","d":"비율을 소수로 나타낼 때 소수 첫째 자리를 '할', [둘째 자리를 '푼', 셋째를 '리'~첫째를 '푼'~둘째를 '리']라고 읽는 방법이에요.","ex":"0.625 = 6할 2푼 5리","x":"0.3은 3푼이에요.","why":"소수 첫째 자리는 '할'이라 0.3은 3할이에요.","ln":["비율","소수(小數)"]},{"w":"타율","en":"batting average","d":"야구에서 [타수에 대한 안타 수의~안타에 대한 타수의~홈런의] 비율이에요.","ex":"10타수 3안타 → 타율 0.3 (3할)","x":"타율 0.311은 3푼 1리 1할이에요.","why":"0.311은 3할 1푼 1리예요.","ln":["비율","할푼리"]},{"w":"이자","en":"interest","d":"돈을 [빌리거나 맡긴 대가로~물건을 사고~선물로] 주고받는 돈이에요.","ex":"은행에 맡긴 돈에 붙는 이자","x":"이자는 돈을 빌린 사람이 받아요.","why":"돈을 빌린 사람은 이자를 내고, 빌려준 사람이 받아요.","ln":["비율"]},{"w":"이율","en":"interest rate","d":"[원금에 대한 이자의~이자에 대한 원금의~원금과 이자의 합의] 비율이에요.","ex":"10000원 맡기고 이자 600원 → 이율 6%","x":"이율 6%면 10000원에 이자가 6원이에요.","why":"10000원의 6/100은 600원이에요.","ln":["비율","이자"]},{"w":"농도","en":"concentration","d":"용액 속에 [녹아 있는 물질의 양의 비율~물의 무게~용기의 크기]이에요. %로 나타내요.","ex":"소금물 100g에 소금 10g → 농도 10%","x":"물을 더 넣으면 소금물이 진해져요.","why":"물을 더 넣으면 소금 비율이 낮아져 묽어져요.","ln":["퍼센트"]},{"w":"속력","en":"speed","d":"[단위 시간 동안 이동한 거리~이동한 시간~무게]예요.","ex":"1시간에 3km → 시속 3km","x":"속력 = 시간 ÷ 거리예요.","why":"속력 = 거리 ÷ 시간이에요.","ln":["단위"]}]},{"n":"비례","id":"rel-prop","t":[{"w":"비례식","en":"proportion","d":"비의 값이 같은 두 비를 [등호로 나타낸~더한~빼서 쓴] 식이에요.","ex":"2 : 3 = 4 : 6","x":"비례식에서 내항의 곱과 외항의 곱은 달라요.","why":"비례식에서는 내항의 곱과 외항의 곱이 같아요: 3 × 4 = 2 × 6.","ln":["비","비례"]},{"w":"항","en":"term","d":"비에서 [:의 앞뒤에 있는 각 수~기호 :~등호]예요. 식에서는 +, −로 연결된 각 부분이에요.","ex":"3x + 4y에서 항은 3x와 4y","x":"3x + 4y는 항이 하나예요.","why":"+로 나뉜 3x와 4y, 항이 두 개예요.","ln":["외항","내항","비례식","전항","후항"]},{"w":"내항","en":"inner terms","d":"비례식에서 [안쪽에 있는~바깥쪽에 있는~맨 앞의] 두 항이에요.","ex":"2 : 3 = 4 : 6에서 내항은 3과 4","x":"2 : 3 = 4 : 6에서 내항은 2와 6이에요.","why":"2와 6은 바깥쪽 외항이에요. 안쪽 3과 4가 내항이에요.","ln":["외항","비례식"]},{"w":"외항","en":"outer terms","d":"비례식에서 [바깥쪽에 있는~안쪽에 있는~가운데] 두 항이에요.","ex":"2 : 3 = 4 : 6에서 외항은 2와 6","x":"외항의 곱이 내항의 곱보다 늘 커요.","why":"비례식에서는 두 곱이 늘 같아요.","ln":["내항","비례식"]},{"w":"비례","en":"proportion (relation)","d":"두 양에서 한쪽이 2배, 3배가 될 때 [다른 쪽도 2배, 3배가 되는~다른 쪽은 그대로인~다른 쪽은 1씩 커지는] 관계예요. 정비례라고도 해요.","ex":"공책 1권 1000원, 2권 2000원","x":"한쪽이 1씩 커질 때 다른 쪽도 1씩 커지면 늘 비례예요.","why":"2배, 3배로 같이 늘어야 비례예요. 5, 6, 7처럼 1씩 더해지기만 하면 아닐 수 있어요.","ln":["비","관계식"]},{"w":"비례배분","en":"proportional distribution","d":"전체를 [주어진 비로 나누는~똑같이 나누는~아무렇게나 나누는] 것이에요.","ex":"12000원을 2 : 1로 → 8000원, 4000원","x":"2 : 1로 나누면 한 사람이 2원 더 받아요.","why":"전체를 3몫으로 보고 2몫, 1몫씩 나눠요.","ln":["비"]},{"w":"연비","en":"continued ratio","d":"[셋 이상의 양을~두 양만~하나의 양을] 비로 나타낸 것이에요.","ex":"사과 : 배 : 귤 = 3 : 3 : 5","x":"연비는 꼭 두 수로만 써요.","why":"연비는 세 수 이상을 한꺼번에 비로 나타내요.","ln":["비"]}]},{"n":"식과 방정식","id":"rel-eq","t":[{"w":"식","en":"expression","d":"숫자, 문자, [연산 기호~그림~색깔]를 써서 내용을 간단히 나타낸 것이에요.","ex":"3 + 4, 2 × x","x":"식에는 꼭 등호가 있어야 해요.","why":"3 + 4처럼 등호 없는 식도 식이에요.","ln":["기호","부등식","등식"]},{"w":"등식","en":"equation (equality)","d":"[등호(=)를 써서~부등호(<)를 써서~괄호만 써서] 두 양이 같음을 나타낸 식이에요.","ex":"3 + 4 = 7","x":"3 + 4 > 5도 등식이에요.","why":">를 쓴 식은 부등식이에요.","ln":["부등식","식"]},{"w":"등호","en":"equal sign","d":"두 수나 식이 [서로 같음을~더 큼을~더 작음을] 나타내는 기호 =예요.","ex":"2 + 3 = 5","x":"등호는 '답을 써라'는 뜻이에요.","why":"등호는 양쪽 값이 같다는 뜻이에요: 5 = 2 + 3도 맞아요.","ln":["부등호"]},{"w":"양변","en":"both sides","d":"등식에서 [등호의 왼쪽과 오른쪽~등호만~맨 앞 수]을 함께 부르는 말이에요.","ex":"(2 + 5) × 3 = 7 × 3에서 왼쪽 (2 + 5) × 3, 오른쪽 7 × 3","x":"양변에 같은 수를 더하면 등식이 깨져요.","why":"양변에 같은 수를 더하거나 곱해도 등식은 그대로 성립해요.","ln":["등식","등호"]},{"w":"부등호","en":"inequality sign","d":"두 수의 크기가 [같지 않음을~같음을~더해짐을] 나타내는 기호 <, >예요.","ex":"4 < 7, 7 > 4","x":"부등호는 작은 수 쪽으로 벌어져요.","why":"벌어진 쪽에 큰 수가 와요: 7 > 4.","ln":["부등식"]},{"w":"부등식","en":"inequality","d":"[부등호를 써서~등호를 써서~괄호를 써서] 크기를 비교한 식이에요.","ex":"13 < 15, □ + 2 < 30","x":"부등식은 답이 딱 하나예요.","why":"□ + 2 < 30처럼 답이 여러 개일 때가 많아요.","ln":["부등호"]},{"w":"어떤 수","en":"some number","d":"아직 값을 [모르는~알고 있는~이미 쓴] 수예요. 보통 □로 나타내요.","ex":"사탕 3개 + □개 = 7개 → □ = 4","x":"어떤 수는 늘 0이에요.","why":"문제에 따라 여러 값이 될 수 있어요.","ln":["미지수"]},{"w":"미지수","en":"unknown","d":"[아직 모르는~이미 알고 있는~답으로 나온] 값을 나타내는 문자예요. 보통 x를 써요.","ex":"x − 5 = 2 → x = 7","x":"미지수는 꼭 x만 써야 해요.","why":"□, y, a 같은 다른 기호나 문자도 쓸 수 있어요.","ln":["방정식"]},{"w":"방정식","en":"equation","d":"[미지수의 값에 따라 참도 되고 거짓도 되는~언제나 참인~언제나 거짓인] 등식이에요.","ex":"□ + 7 = 10 → □ = 3일 때만 참","x":"방정식은 언제나 참이에요.","why":"미지수가 맞는 값일 때만 참이에요.","ln":["등식","미지수"]},{"w":"해","en":"solution","d":"방정식을 [참이 되게 하는~거짓이 되게 하는~더 크게 하는] 미지수의 값이에요.","ex":"□ + 3 = 6의 해는 3","x":"□ + 3 = 6의 해는 9예요.","why":"3을 넣어야 3 + 3 = 6이 돼요.","ln":["근","방정식"]},{"w":"근","en":"root","d":"방정식의 [해를 달리 부르는~계수를 달리 부르는~항을 달리 부르는] 말이에요.","ex":"3x + 2 = 8의 근은 x = 2","x":"근과 해는 다른 뜻이에요.","why":"방정식에서 근과 해는 같은 뜻이에요.","ln":["방정식","해"]},{"w":"항등식","en":"identity","d":"x에 [어떤 값을 넣어도 늘 참인~한 값만 참인~늘 거짓인] 등식이에요.","ex":"x + x = 2 × x","x":"□ + 3 = 6은 항등식이에요.","why":"□가 3일 때만 참이라 방정식이에요.","ln":["식","등식"]},{"w":"일차방정식","en":"linear equation","d":"미지수의 가장 높은 차수가 [1인~2인~0인] 방정식이에요.","ex":"5x + 9 = 0","x":"x² + 1 = 5는 일차방정식이에요.","why":"x²은 차수가 2라서 이차방정식이에요.","ln":["미지수","방정식"]},{"w":"단항식","en":"monomial","d":"[한 개의 항으로만~두 개 이상의 항으로~등호로] 이루어진 식이에요.","ex":"2, ab, 2xy","x":"3x + 1은 단항식이에요.","why":"3x와 1, 항이 두 개라 다항식이에요.","ln":["다항식"]},{"w":"다항식","en":"polynomial","d":"[두 개 이상의 항을 +, −로 연결한~항 하나로 된~등호가 있는] 식이에요.","ex":"ax + by, 3x + 4","x":"다항식에는 항이 하나뿐이에요.","why":"다항식은 항이 둘 이상이에요.","ln":["항"]},{"w":"계수","en":"coefficient","d":"문자가 있는 항에서 [문자에 곱해진 수~문자 그 자체~더해진 수]예요.","ex":"3x² + 2x에서 3과 2가 계수","x":"5x에서 계수는 x예요.","why":"문자 앞에 곱해진 5가 계수예요.","ln":["미지수"]}]}]},{"n":"자료와 가능성","id":"data","br":[{"n":"분류와 표","id":"data-table","t":[{"w":"분류하기","en":"classification","d":"[정한 기준에 따라 나누는~아무렇게나 섞는~크기 순서로 세우는] 것이에요.","ex":"안경 쓴 친구 / 안 쓴 친구","x":"'예쁜 것 / 안 예쁜 것'도 좋은 분류 기준이에요.","why":"사람마다 다르게 나눌 기준은 좋지 않아요. 누가 해도 같게 나뉘어야 해요.","ln":["비교"]},{"w":"가지","en":"kind","d":"어떤 기준에 따라 나눈 [종류의 수~물건의 무게~크기 순서]예요.","ex":"가위바위보에서 낼 수 있는 것: 3가지","x":"가는 길이 3가지면 길이 하나예요.","why":"서로 다른 길이 3개라는 뜻이에요.","ln":["경우의 수"]},{"w":"자료","en":"data","d":"조사하거나 연구할 때 [바탕이 되는 재료~결과 그래프~결론]예요.","ex":"반 친구들이 좋아하는 과일 조사 결과","x":"자료는 그래프로만 나타낼 수 있어요.","why":"자료는 표, 그래프, 글 등 여러 방법으로 나타내요.","ln":["그래프"]},{"w":"표","en":"table","d":"자료를 [한눈에 알아보도록 칸에 정리한~그림만 그린~문장으로 쓴] 것이에요.","ex":"종류와 개수를 칸에 쓴 표","x":"표에는 합계를 쓰면 안 돼요.","why":"합계 칸을 두면 전체 수를 쉽게 알 수 있어요.","fig":"table","ln":["대응표","자료"]}]},{"n":"그래프","id":"data-graph","t":[{"w":"그래프","en":"graph","d":"자료를 [점, 선, 막대, 그림으로 나타낸~글로만 쓴~수로만 쓴] 것이에요.","ex":"막대그래프, 꺾은선그래프, 원그래프","x":"그래프는 표보다 늘 정확해요.","why":"그래프는 한눈에 비교하기 좋고, 정확한 수는 표가 더 잘 보여요.","fig":"bar","ln":["띠그래프","막대그래프","꺾은선그래프","그림그래프","히스토그램"]},{"w":"그림그래프","en":"picture graph","d":"조사한 수를 [그림으로~막대로~선으로] 나타낸 그래프예요.","ex":"큰 그림 = 10, 작은 그림 = 1","x":"그림그래프의 그림은 모두 같은 수를 나타내요.","why":"큰 그림과 작은 그림이 나타내는 수가 다를 수 있어요.","fig":"picg","ln":["그래프"]},{"w":"막대그래프","en":"bar graph","d":"조사한 수를 [막대의 길이로~선으로~원의 넓이로] 나타낸 그래프예요.","ex":"좋아하는 동물별 학생 수를 막대 길이로 나타낸 것","x":"막대가 굵으면 수가 많아요.","why":"막대의 길이(높이)로 수를 비교해요. 굵기는 상관없어요.","fig":"bar","ln":["그래프"]},{"w":"꺾은선그래프","en":"line graph","d":"수량을 점으로 찍고 [선분으로 이은~막대로 세운~원을 나눈] 그래프예요. 변화를 보기 좋아요.","ex":"날마다 잰 콩나물 키를 점으로 찍어 선으로 이은 것","x":"꺾은선그래프는 좋아하는 과일 수를 비교할 때 가장 좋아요.","why":"꺾은선그래프는 시간에 따른 변화를 볼 때 좋아요.","fig":"lineg","ln":["히스토그램","막대그래프"]},{"w":"물결선","en":"wavy line","d":"그래프에서 [필요 없는 부분을 줄여 나타내는~가장 큰 값을 나타내는~0을 표시하는] 물결 모양 선이에요.","ex":"0 ~ 13cm 사이를 물결선으로 줄여요.","x":"물결선 아래는 값이 0이에요.","why":"물결선은 필요 없는 부분을 생략했다는 표시예요.","fig":"lineg","ln":["막대그래프","꺾은선그래프"]},{"w":"띠그래프","en":"band graph","d":"전체를 [띠 모양의 직사각형으로 나누어~원으로 나누어~막대로 세워] 비율을 나타낸 그래프예요.","ex":"좋아하는 색깔의 비율을 긴 띠 하나에 나누어 그린 것","x":"띠그래프 띠 전체는 100%가 아니에요.","why":"띠 전체가 100%예요.","fig":"band","ln":["그래프","원그래프"]},{"w":"원그래프","en":"pie chart","d":"전체를 [원 모양으로 나누어~띠로 나누어~막대로] 비율을 나타낸 그래프예요.","ex":"원 전체 = 100%","x":"원그래프에서 각 부분 합은 50%예요.","why":"모든 부분을 더하면 100%예요.","fig":"pie","ln":["그래프","비율그래프"]},{"w":"비율그래프","en":"rate graph","d":"전체에 대한 [각 부분의 비율을~수의 변화를~막대 길이를] 나타낸 그래프예요.","ex":"띠그래프, 원그래프","x":"막대그래프도 비율그래프예요.","why":"막대그래프는 수량을 비교해요. 비율그래프는 띠·원그래프예요.","fig":"pie","ln":["비율","띠그래프","원그래프"]},{"w":"평균","en":"mean","d":"자료 값을 [모두 더해 자료의 개수로 나눈~가장 큰 값과 작은 값을 더한~가장 많이 나온] 값이에요.","ex":"80, 100, 70, 90 → (80 + 100 + 70 + 90) ÷ 4 = 85","x":"평균은 자료 중 하나와 꼭 같아요.","why":"85점을 받은 사람이 없어도 평균은 85일 수 있어요.","ln":["자료"]}]},{"n":"도수","id":"data-freq","t":[{"w":"계급","en":"class","d":"자료를 [일정한 간격으로 나눈 구간~가장 큰 값~자료의 개수]이에요.","ex":"키 140 이상 ~ 145 미만","x":"계급은 간격이 제각각이어도 돼요.","why":"계급은 같은 간격으로 나눠요.","fig":"freqtab","ln":["도수분포표","도수"]},{"w":"도수","en":"frequency","d":"각 계급에 [속하는 자료의 수~속하는 자료의 합~가장 큰 값]예요.","ex":"145 ~ 150cm 학생 11명 → 도수 11","x":"도수는 그 계급 자료 값을 모두 더한 거예요.","why":"도수는 그 계급에 든 자료가 몇 개인지예요.","fig":"freqtab","ln":["누적도수","도수분포표"]},{"w":"도수분포표","en":"frequency table","d":"자료를 [계급별 도수로 정리한~크기 순서로 쓴~그림으로 그린] 표예요.","ex":"키 구간별 학생 수 표","x":"도수분포표에는 자료 값이 하나하나 다 보여요.","why":"도수분포표는 구간별 개수만 보여요.","fig":"freqtab","ln":["도수","표"]},{"w":"누적도수","en":"cumulative frequency","d":"[처음 계급부터 그 계급까지 도수를 차례로 더한 값~그 계급의 도수만~가장 큰 도수]이에요.","ex":"150cm 미만 누적도수 = 2 + 11 = 13","x":"누적도수는 계급이 올라갈수록 작아질 수 있어요.","why":"도수를 계속 더하니까 작아지지 않아요.","ln":["도수","계급"]},{"w":"히스토그램","en":"histogram","d":"도수분포표를 [가로는 계급, 세로는 도수인 직사각형으로~원으로~선으로만] 나타낸 그래프예요.","ex":"키 구간별 학생 수 기둥","x":"히스토그램은 막대 사이를 띄워 그려요.","why":"계급이 이어지니까 기둥을 붙여 그려요.","fig":"hist","ln":["도수분포표","막대그래프"]},{"w":"줄기와 잎 그림","en":"stem-and-leaf plot","d":"자료의 [큰 자릿값은 줄기, 작은 자릿값은 잎으로~모두 한 줄로~그림으로만] 나타낸 그림이에요.","ex":"25 → 줄기 2, 잎 5","x":"줄기와 잎 그림에서는 원래 자료 값을 알 수 없어요.","why":"줄기와 잎을 붙이면 원래 값을 그대로 알 수 있어요.","ln":["자료","표"]}]},{"n":"경우의 수와 확률","id":"data-prob","t":[{"w":"경우의 수","en":"number of cases","d":"어떤 일이 일어날 수 있는 [가짓수~가능성의 비율~결과의 합]예요.","ex":"주사위 1개 → 6가지","x":"동전 1개를 던질 때 경우의 수는 1이에요.","why":"앞면, 뒷면 2가지예요.","ln":["확률","사건"]},{"w":"사건","en":"event","d":"같은 조건에서 [여러 번 해 볼 때 일어나는 결과~딱 한 번만 일어나는 일~일어나지 않는 일]예요.","ex":"주사위를 던져 4가 나오는 것","x":"주사위에서 '짝수가 나오는 것'은 사건이 아니에요.","why":"2, 4, 6이 나오는 결과를 모은 것도 사건이에요.","ln":["경우의 수"]},{"w":"나뭇가지 그림","en":"tree diagram","d":"일어날 수 있는 경우를 [나뭇가지처럼 펼쳐~한 줄로~원 안에] 나타낸 그림이에요.","ex":"빨강·파랑·노랑 공 2개 차례로 꺼내기 → 6가지","x":"나뭇가지 그림은 경우를 빠뜨리기 쉬워요.","why":"가지를 차례로 그리면 빠뜨리거나 겹치지 않게 셀 수 있어요.","fig":"tree","ln":["경우의 수"]},{"w":"확률","en":"probability","d":"모든 경우의 수에 대한 [어떤 사건이 일어나는 경우의 수의~일어나지 않는 경우의~전체 경우의] 비율이에요.","ex":"주사위에서 홀수가 나올 확률 = 3/6 = 1/2","x":"확률은 1보다 클 수 있어요.","why":"확률은 0부터 1까지예요.","ln":["경우의 수","비율"]},{"w":"동전","en":"coin","d":"금속으로 만든 [둥글납작한 돈~종이 돈~카드]이에요. 앞면과 뒷면이 있어요.","ex":"동전 던지기: 앞면 또는 뒷면","x":"동전을 던지면 앞면이 나올 확률이 더 커요.","why":"앞면과 뒷면이 나올 확률은 똑같이 1/2이에요.","ln":["경우의 수"]},{"w":"주사위","en":"dice","d":"각 면에 [1부터 6까지의 눈을 새긴~숫자 없는~1부터 10까지 쓴] 정육면체예요.","ex":"마주 보는 두 면의 눈을 더하면 7","x":"주사위에서 1과 2는 마주 보는 면이에요.","why":"마주 보는 면의 합이 7이라 1의 반대편은 6이에요.","fig":"dice","ln":["확률"]},{"w":"가위바위보","en":"rock paper scissors","d":"[손으로 가위, 바위, 보를 내어~주사위로~동전으로] 승부를 정하는 놀이예요.","ex":"두 사람이 하면 경우의 수 3 × 3 = 9","x":"두 사람이 가위바위보를 하는 경우의 수는 3이에요.","why":"한 사람마다 3가지라 3 × 3 = 9가지예요.","ln":["주사위"]}]},{"n":"집합","id":"data-set","t":[{"w":"집합","en":"set","d":"[대상을 분명히 가를 수 있는~예쁘다처럼 사람마다 다른~딱 하나뿐인] 것들의 모임이에요.","ex":"10보다 작은 자연수의 모임","x":"'키 큰 친구의 모임'은 집합이에요.","why":"'키 큰'은 사람마다 달라서 집합이 아니에요.","fig":"venn","ln":["합집합","부분집합"]},{"w":"부분집합","en":"subset","d":"집합 A의 원소가 [모두 집합 B에 속할 때~하나만 B에 속할 때~B에 하나도 없을 때] A를 B의 부분집합이라고 해요.","ex":"{1, 2}는 {1, 2, 3}의 부분집합","x":"원소 하나만 겹치면 부분집합이에요.","why":"A의 원소가 모두 B에 들어 있어야 해요.","fig":"venn","ln":["집합","교집합","합집합"]},{"w":"교집합","en":"intersection","d":"두 집합에 [동시에 속하는~하나라도 속하는~어디에도 없는] 원소들의 집합이에요. A ∩ B로 써요.","ex":"{1, 2, 3} ∩ {2, 3, 4} = {2, 3}","x":"교집합은 두 집합을 모두 합친 거예요.","why":"모두 합친 것은 합집합이에요. 교집합은 겹친 부분이에요.","fig":"venn","ln":["집합","합집합"]},{"w":"합집합","en":"union","d":"두 집합의 원소를 [모두 모은~겹친 것만 모은~하나도 안 모은] 집합이에요. A ∪ B로 써요.","ex":"짝수 ∪ 홀수 = 자연수","x":"합집합에서는 겹친 원소를 두 번 써요.","why":"같은 원소는 한 번만 써요.","fig":"venn","ln":["집합","교집합"]},{"w":"벤다이어그램","en":"Venn diagram","d":"집합 사이의 관계를 [원 같은 도형으로 그린~표로 쓴~막대로 세운] 그림이에요.","ex":"두 원이 겹친 부분 = 교집합","x":"벤다이어그램에서 원이 겹친 곳은 아무 뜻이 없어요.","why":"겹친 곳에 두 집합 모두의 원소가 들어가요.","fig":"venn","ln":["집합"]}]}]},{"n":"문제 해결","id":"solve","br":[{"n":"문제 해결 방법","id":"solve-how","t":[{"w":"문제 해결","en":"problem solving","d":"[알고 있는 것과 자료를 이용해 목표에 이르는~답만 외워 쓰는~계산만 연습하는] 것이에요.","ex":"그림 그리기, 표 만들기, 규칙 찾기, 거꾸로 풀기","x":"문제 해결 방법은 한 가지만 있어요.","why":"그림·표·규칙 찾기·예상과 확인 등 여러 방법이 있어요.","ln":["문장제"]},{"w":"문장제","en":"word problem","d":"생활에서 생길 수 있는 상황을 [말로 풀어 쓴~식으로만 쓴~그림으로만 그린] 수학 문제예요.","ex":"사과 2개와 배 3개를 샀어요. 과일은 모두 몇 개일까요?","x":"문장제는 숫자만 찾아 아무 계산이나 하면 돼요.","why":"무엇을 묻는지, 조건이 무엇인지 끝까지 읽어야 식을 바르게 세울 수 있어요.","ln":["문제 해결"]},{"w":"예상과 확인","en":"guess and check","d":"답을 [먼저 예상해 보고 맞는지 확인하는~확인 없이 바로 쓰는~남의 답을 보는] 방법이에요. 틀리면 다시 예상해요.","ex":"두발·세발 자전거 5대, 바퀴 13개 → 예상 2대·3대 → 4 + 9 = 13 ✓","x":"한 번 예상하면 확인하지 않아도 돼요.","why":"예상한 값이 조건에 맞는지 꼭 확인해야 해요.","ln":["문제 해결"]},{"w":"거꾸로 풀기","en":"working backward","d":"결과에서 출발해 [처음으로 거슬러 올라가며~앞에서부터~아무 데서나] 푸는 방법이에요.","ex":"□ + 8 = 10 → □ = 10 − 8 = 2","x":"거꾸로 풀 때도 더하기는 그대로 더하기로 해요.","why":"거꾸로 갈 때는 반대로 해요: 더했으면 빼고, 곱했으면 나눠요.","ln":["검산"]}]}]}];
